        public string savedocumentinprovided(string filename)
        {
            string apiUrl = $"https://api.weverifyglobal.com/CaseDocsFromAPI?fileName={filename}";
            WebClient webClient = new WebClient();
            byte[] fileBytes = webClient.DownloadData(apiUrl);
            string PathDoc = "~/Documents/CandidateDocuments/ProvidedDocuments/";
            string absolutePathDoc = HttpContext.Current.Server.MapPath(PathDoc);

            if (fileBytes.Length > 0)
            {
                string DocumentType = "Document";
                string ext = Path.GetExtension(filename);
                string originalFileName = Path.GetFileNameWithoutExtension(filename);
                string uniqueFileName = $"{originalFileName}{ext}";


                var provideddocumentsPath = HttpContext.Current.Server.MapPath(PathDoc + uniqueFileName);
                var filePath = Path.Combine(absolutePathDoc, uniqueFileName);


                File.WriteAllBytes(filePath, fileBytes);
                Console.WriteLine($"Document saved successfully at {filePath}");
            }
            else
            {
                Console.WriteLine("The document could not be downloaded.");
            }
            return "Ok";
        }
