        public string API_Fractal_GeteData(JsonDataFractal request)
        {
            string responsedata = "";
            try
            {
                DataTable dt = new DataTable();
                dt = GetClientAPIByClientRowId(679, "BGVReport");
                string EndPoint = dt.Rows[0]["EndPoint"].ToString();
                string UName = dt.Rows[0]["UserName"].ToString();
                string psw = dt.Rows[0]["Password"].ToString();
                string apiKey = dt.Rows[0]["AuthorizationKey"].ToString();

                string res = "";
                var doc = new XmlDocument();
                string path = System.Web.Hosting.HostingEnvironment.MapPath("~/Documents");
                string fileName = "data.xml";
                string fileSavePath = Path.Combine(path, fileName);
                doc.Load(fileSavePath);
                string strData = "";
                if (doc.InnerText != "")
                {

                    doc.GetElementsByTagName("wd:Status_Date")[0].InnerText = request.Status_Date;
                    doc.GetElementsByTagName("wd:Status_Comment")[0].InnerText = request.Status_Comment;
                    doc.GetElementsByTagName("wd:Package_Comment")[0].InnerText = request.Package_Comment;
                    doc.GetElementsByTagName("wd:Results_URL")[0].InnerText = request.Results_URL;
                    //request.Background_Check_Package_ID = "FAPL_Lateral_Hiring_India";
                    //request.Background_Check_Status_ID = "Fractal Review Required";
                    foreach (XmlElement _XmlElement in doc.GetElementsByTagName("wd:ID"))
                    {
                        string x = _XmlElement.Attributes["wd:type"].Value;
                        if (x == "Background_Check_ID")
                        {
                            _XmlElement.InnerText = request.Background_Check_ID;
                        }
                        else if (x == "Background_Check_Status_ID")
                        {
                            _XmlElement.InnerText = request.Background_Check_Status_ID;
                        }
                        else if (x == "Background_Check_Package_ID")
                        {
                            _XmlElement.InnerText = request.Background_Check_Package_ID;
                        }
                    }
                    strData = ConvertToString(doc);
                }
                HttpWebRequest request1 = (HttpWebRequest)WebRequest.Create(EndPoint);

                byte[] requestInFormOfBytes = System.Text.Encoding.ASCII.GetBytes(strData);
                request1.Method = "POST";
                request1.ContentType = "text/xml;charset=utf-8";
                request1.ContentLength = requestInFormOfBytes.Length;
                Stream requestStream = request1.GetRequestStream();
                requestStream.Write(requestInFormOfBytes, 0, requestInFormOfBytes.Length);
                requestStream.Close();

                HttpWebResponse response = (HttpWebResponse)request1.GetResponse();
                StreamReader respStream = new StreamReader(response.GetResponseStream(), System.Text.Encoding.Default);
                res = respStream.ReadToEnd();
                respStream.Close();
                response.Close();
                var doc1 = new XmlDocument();
                doc1.LoadXml(res);
                if (doc1.InnerText != "")
                {
                    string WID = "";
                    string Background_Check_ID = "";
                    foreach (XmlElement _XmlElement in doc1.GetElementsByTagName("wd:ID"))
                    {
                        string x = _XmlElement.Attributes["wd:type"].Value;
                        if (x == "WID")
                        {
                            WID = _XmlElement.InnerText;
                        }
                        else if (x == "Background_Check_ID")
                        {
                            Background_Check_ID = _XmlElement.InnerText;
                        }
                    }
                    responsedata = "WID:" + WID + "&&Background_Check_ID:" + Background_Check_ID;
                }
                if (responsedata == "")
                {
                    responsedata = "Get No Data in Response";
                }
                InsertAPI_AuditDetail(request.Background_Check_ID, 679, "Success", "UploadReport", request.Background_Check_ID + "," + request.Background_Check_Package_ID, responsedata, "API");
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(request.Background_Check_ID, 679, "Failed", "UploadReport", responsedata, ex.Message, "API");
                return ex.Message;
            }

            return responsedata;
        }

        public string ConvertToString(XmlDocument xmlDoc)
        {
            using (StringWriter sw = new StringWriter())
            {
                using (XmlTextWriter tx = new XmlTextWriter(sw))
                {
                    xmlDoc.WriteTo(tx);
                    string strXmlText = sw.ToString();
                    return strXmlText;
                }
            }
        }
