        public void API_IGT_UploadReport(string _ClientRefID, string _module, string _description, string _fileName, string reportInBase64, string report_status)
        {
            try
            {
                DataTable dt = new DataTable();
                dt = GetClientAPIByClientRowId(695, "BGVReport");
                string EndPoint = dt.Rows[0]["EndPoint"].ToString();
                string UName = dt.Rows[0]["UserName"].ToString();
                string psw = dt.Rows[0]["Password"].ToString();

                int _externalId = Convert.ToInt32(_ClientRefID);
                var httpWebRequest = (HttpWebRequest)WebRequest.Create(EndPoint);
                httpWebRequest.ContentType = "application/json";
                httpWebRequest.Method = "POST";
                var plainTextBytes = System.Text.Encoding.UTF8.GetBytes(UName + ":" + psw);
                string val = System.Convert.ToBase64String(plainTextBytes);
                httpWebRequest.Headers.Add("Authorization", "Basic " + val);
                using (var streamWriter = new
                StreamWriter(httpWebRequest.GetRequestStream()))
                {
                    string json = new JavaScriptSerializer().Serialize(new
                    {
                        userId = "SF_BGV",
                        externalId = _externalId,
                        fileName = _fileName,
                        module = _module,
                        description = _description,
                        fileContent = reportInBase64,
                        viewable = true,
                        deletable = false
                    });
                    streamWriter.Write(json);
                }
                var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse();
                var jsonresult = string.Empty;
                using (var streamReader = new StreamReader(httpResponse.GetResponseStream()))
                {
                    jsonresult = streamReader.ReadToEnd();
                }
                IGT_Entity igt = JsonConvert.DeserializeObject<IGT_Entity>(jsonresult);
                string attachmentid = igt.D.attachmentId;
                Update_IGT_StatusByAttachmentID(attachmentid, _ClientRefID, report_status);
                InsertAPI_AuditDetail(_ClientRefID, 695, "Success", "UploadReport", "attachmentid:" + attachmentid + ",Req:" + _module + "," + report_status + "" + _description, "Report Uploaded Successfully", "API");
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(_ClientRefID, 695, "Failed", "UploadReport", _module + "," + report_status + "" + _description, ex.Message, "API");
            }
        }

