        public void UpdateAPINewCaseInitiateStatus(int personalRowId, string clientRowId, string actionType)
        {
            int clientId = Convert.ToInt32(clientRowId);
            try
            {
                if (clientRowId == "249" || clientRowId == "277")
                {
                    APIResponse apiResponse = new APIResponse();
                    DataTable dt = cc.GetPersonalInfo(personalRowId);
                    string ClientRefId = dt.Rows[0]["ClientRefId"].ToString();
                    string CompanyRefNo = dt.Rows[0]["CompanyRefNo"].ToString();
                    string InitiatedDate = dt.Rows[0]["OrderDate"].ToString();
                    if (actionType == "AddCaseCRC" || actionType == "AddCaseCRC_Bulk")
                    {
                        SutherlandCRC_StatusAPI(ClientRefId, CompanyRefNo, "Yellow", "", "WIP", "", "", InitiatedDate, "", "", "", actionType);
                    }
                    else
                    {
                        apiResponse = SutherlandStatusAPI("", ClientRefId, CompanyRefNo, "WIP", "Yellow", "", "", InitiatedDate);
                        apiResponse.apiRequestData = "PersonalRowId:" + personalRowId + ",CompanyRefNo:" + CompanyRefNo + ",InitiatedDate:" + InitiatedDate + ",Status:WIP,Color:Yellow";
                        InsertAPI_AuditDetail(ClientRefId, clientId, apiResponse.status, actionType + ":Case Initiated", apiResponse.apiRequestData, apiResponse.apiResponseData, "API");
                    }
                }
                else if (clientRowId == "8" && actionType == "ClientCaseApprove")
                {
                    DataTable dt = cc.GetPersonalInfoByTempPersonalRowID(personalRowId);
                    int ClientUserRowID = Convert.ToInt32(dt.Rows[0]["ClientUserRowID"]);
                    if (ClientUserRowID == 3082)
                    {
                        string ClientRefId = dt.Rows[0]["ClientRefId"].ToString(); //customerId
                        string EmployeeID = dt.Rows[0]["EmployeeID"].ToString(); //personId
                        string completedDate = DateTime.UtcNow.ToString("MM/dd/yyyy HH:mm:ss");
                        CventReportStatus(ClientRefId, EmployeeID, "D37002026006", "In-Progress Vendor", completedDate, "", "ClientCaseApprove");
                    }
                }
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail("", clientId, "Failed", actionType + ":Case Initiated", "PersonalRowId:" + personalRowId, ex.Message, "API");
            }
        }
