        private string PutTitanBgvtStatus(string uniqueID, string reportUrl, string bgvStatus, string reportFileName, string bgvComment, int clientRowId, int PersonalRowId, string bgvReportStatus, string StrData, string CompanyRefNo)
        {
            string apiResponse = "";
            try
            {
                string strUrl = "";
                string Strservice_id = "";
                if (bgvReportStatus == "BGV1")
                {
                    Strservice_id = "?service_id=Court and ID Verification";
                    // strUrl = "https://api.zwayam.com/bgv/v1/candidate/" + uniqueID + "/bgv_status" + Strservice_id;
                    ///========================Below Url using Live Server======================
                    strUrl = "https://apipreprod1.zwayam.com/bgv/v1/candidate/" + uniqueID + "/bgv_status" + Strservice_id;
                }
                else if (bgvReportStatus == "BGV2")
                {
                    Strservice_id = "?service_id=Education, Reference and Previous Employment";
                    //strUrl = "https://api.zwayam.com/bgv/v1/candidate/" + uniqueID + "/bgv_status" + Strservice_id;
                    ///========================Below Url using Live Server======================
                    strUrl = "https://apipreprod1.zwayam.com/bgv/v1/candidate/" + uniqueID + "/bgv_status" + Strservice_id;
                }
                else if (bgvReportStatus == "BGV3")
                {
                    Strservice_id = "?service_id=Current Employment";
                    //strUrl = "https://api.zwayam.com/bgv/v1/candidate/" + uniqueID + "/bgv_status" + Strservice_id;
                    ///========================Below Url using Live Server======================
                    strUrl = "https://apipreprod1.zwayam.com/bgv/v1/candidate/" + uniqueID + "/bgv_status" + Strservice_id;
                }
                string Api_Key = "";
                var ClientAuth = Dc.SP_GetClientAPIDetails(clientRowId, "API KEY", "BGVStatus");
                if (ClientAuth.Rows.Count > 0)
                {
                    Api_Key = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]);
                }

                HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(strUrl.Trim());
                httpWebRequest.Method = "PUT";
                httpWebRequest.ContentType = "application/json";
                ///========================Below Url using Live Server======================
                httpWebRequest.Headers.Add("api_key", Api_Key);
                StrBuilderObj.Clear();
                string json = "";
                using (var streamWriter = new
                StreamWriter(httpWebRequest.GetRequestStream()))
                {
                    if (reportUrl != "")
                    {
                        json = "{\"vendorId\":\"" + "SECURITAS" + "\",\"verificationReferenceId\":\"" + CompanyRefNo + "\",\"status\":\"" + bgvStatus.ToUpper() + "\",\"reportUrl\":\"" + reportUrl + "\",\"reportFileName\":\"" + reportFileName + "\",\"message\":\"" + bgvComment + "\"}";

                    }
                    else
                    {
                        json = new JavaScriptSerializer().Serialize(new
                        {
                            vendorId = "SECURITAS",
                            verificationReferenceId = CompanyRefNo,
                            status = bgvStatus.ToUpper(),
                            reportUrl = reportUrl,
                            reportFileName = reportFileName,
                            message = bgvComment
                        });
                    }
                    streamWriter.Write(json);
                }
                StrBuilderObj.Append(json.ToString());
                var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse();
                apiResponse = httpResponse.StatusCode.ToString();
                if (apiResponse == "OK")
                {
                    InsertAPI_AuditDetail(uniqueID, clientRowId, "Success", "TitanReport", "RequestData:" + StrData, apiResponse, "API");
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("----------------------------API Response-----------------");
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("Response:Success  DataType:TitanReport");
                    //WriteLog(StrBuilderObj.ToString(), "", "", "Titan", "SendStatusAndReport", clientRowId + "-" + PersonalRowId + "-Success");
                }
                else
                {
                    InsertAPI_AuditDetail(uniqueID, clientRowId, "Failed", "BgvStatus", "RequestData:" + StrData, apiResponse, "API");
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("----------------------------API Response-----------------");
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("Response:Failed  DataType:BGVStatus" + apiResponse.ToString());
                    WriteLog(StrBuilderObj.ToString(), "", "", "Titan", "SendStatusAndReport", clientRowId + "-" + PersonalRowId + "-Failed");
                }
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(uniqueID, clientRowId, "Failed", "BgvStatus", "RequestData:" + StrData, "Exception:" + ex.Message, "API");
                string msg = ex.Message;
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("----------------------------API Response-----------------");
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("Response:Failed  DataType:BGVStatus  " + "Exception:" + msg);
                WriteLog(StrBuilderObj.ToString(), "", "", "Titan", "SendStatusAndReport", clientRowId + "-" + PersonalRowId + "-Exception-Failed");
            }
            return apiResponse;
        }
