        private static Token GetAccessTokenold(string username, string password)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
            Token token = new Token();
            try
            {

                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("----------------------------API GetAccessToken-----------------username:" + username + "clientRowId:" + 990 + " personalRowId:" + "personalRowId");
                StrBuilderObj.Append(Environment.NewLine);
                //// string baseAddress = "https://LTIiVerifyTestAPI.azurewebsites.net/TOKEN";
                ////============Production=========
                string baseAddress = "https://ltiiverifyapiprodnew.azurewebsites.net/TOKEN";
                HttpClientHandler handler = new HttpClientHandler();
                HttpClient client = new HttpClient(handler);
                var RequestBody = new Dictionary<string, string>
                {
                {"grant_type", "password"},
                {"username", username},
                {"password", password},
                };
                var tokenResponse = client.PostAsync(baseAddress, new FormUrlEncodedContent(RequestBody)).Result;

                if (tokenResponse.IsSuccessStatusCode)
                {
                    var JsonContent = tokenResponse.Content.ReadAsStringAsync().Result;
                    token = new JavaScriptSerializer().Deserialize<Token>(JsonContent);
                    token.error = null;
                }
                else
                {
                    token.error = "Not able to generate Access Token Invalid usrename or password";
                }
            }
            catch (WebException ex)
            {
                token.error = "WebException occurred while calling Token API.";

                WriteLog(token.error + " Error: " + ex.Message, "", "", "LTIClientReviewStatus", "GetAccessToken", "Error");
                InsertAPI_AuditDetail_LTIToke("token", 990, "Failed", ex.Message, "HttpRequestException:" + ex.ToString(), "", "API", 0);
                if (ex.Response != null)
                {
                    using (var reader = new StreamReader(ex.Response.GetResponseStream()))
                    {
                        string responseText = reader.ReadToEnd();
                        WriteLog("WebException Response: " + responseText, "", "", "LTIClientReviewStatus", "GetAccessToken", "Error");
                        InsertAPI_AuditDetail_LTIToke("token", 990, "Failed", responseText, "HttpRequestException:" + ex.ToString(), "", "API", 0);

                    }
                }
            }
            catch (Exception ex)
            {
                token.error = "Unexpected error occurred.";
                WriteLog(token.error + " Error: " + ex.ToString(), "", "", "LTIClientTokenStatus", "GetAccessToken", "Error");
                InsertAPI_AuditDetail_LTIToke("token", 990, "Failed", ex.ToString(), "Exception:" + ex.ToString(), "", "API", 0);
            }
            return token;
        }
        private static Token GetAccessToken(string username, string password)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            Token token = new Token();

            try
            {
                // Force TLS 1.2
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("----------------------------API GetAccessToken-----------------username:"
                    + username + " clientRowId:" + 990);
                StrBuilderObj.Append(Environment.NewLine);

                string baseAddress = "https://ltiiverifyapiprodnew.azurewebsites.net/TOKEN";

                using (HttpClientHandler handler = new HttpClientHandler())
                using (HttpClient client = new HttpClient(handler))
                {
                    client.Timeout = TimeSpan.FromSeconds(60);

                    var requestBody = new Dictionary<string, string>
            {
                {"grant_type", "password"},
                {"username", username},
                {"password", password}
            };

                    HttpResponseMessage tokenResponse =
                        client.PostAsync(baseAddress,
                        new FormUrlEncodedContent(requestBody)).Result;

                    if (tokenResponse.IsSuccessStatusCode)
                    {
                        string jsonContent =
                            tokenResponse.Content.ReadAsStringAsync().Result;

                        token = new JavaScriptSerializer()
                            .Deserialize<Token>(jsonContent);

                        token.error = null;
                    }
                    else
                    {
                        token.error = "Not able to generate Access Token. Invalid username or password.";

                        string responseText =
                            tokenResponse.Content.ReadAsStringAsync().Result;

                        WriteLog(responseText, "", "", "LTIClientTokenStatus",
                            "GetAccessToken", "Error");
                    }
                }
            }
            catch (AggregateException ex)
            {
                token.error = "SSL/TLS or HTTP request error.";

                string error =
                    ex.InnerException != null
                    ? ex.InnerException.ToString()
                    : ex.ToString();

                WriteLog(error, "", "", "LTIClientTokenStatus",
                    "GetAccessToken", "Error");

                InsertAPI_AuditDetail_LTIToke("token", 990,"Failed", error, error,"", "API",0);
            }
            catch (Exception ex)
            {
                token.error = "Unexpected error occurred.";

                WriteLog(ex.ToString(), "", "", "LTIClientTokenStatus",
                    "GetAccessToken", "Error");

                InsertAPI_AuditDetail_LTIToke(
                    "token",
                    990,
                    "Failed",
                    ex.ToString(),
                    ex.ToString(),
                    "",
                    "API",
                    0);
            }

            return token;
        }
