        private string Convertbase64FromFiles(string fileName)
        {
            string filePath = System.Web.HttpContext.Current.Server.MapPath("~/Documents/CandidateReport/" + fileName);
            byte[] AsBytes = File.ReadAllBytes(filePath);
            String AsBase64String = Convert.ToBase64String(AsBytes);
            return AsBase64String;

        }
        private static string Convertbase64FromFilesClientReview(string fileName)
        {
            string filePath = System.Web.HttpContext.Current.Server.MapPath("~/Documents/CandidateDocuments/ProvidedDocuments/" + fileName);
            byte[] AsBytes = File.ReadAllBytes(filePath);
            String AsBase64String = Convert.ToBase64String(AsBytes);
            return AsBase64String;

        }
