        private void SutherlandCRC_StatusAPI(string ClientRefId, string CompanyRefNo, string ColorCode, string reportType, string status, string ReportName = "", string ReportPath = "", string InitiatedDate = "", string CompletionDate = "", string VendorComments = "", string VendorSLA = "", string actionType = "")
        {
            try
            {
                Thread.Sleep(1000);
                DataTable dt = new DataTable();
                dt = GetClientAPIByClientRowId(249, "CRCReport");
                string EndPoint = dt.Rows[0]["EndPoint"].ToString();
                string apiKey = dt.Rows[0]["AuthorizationKey"].ToString();
                //var client = new RestClient("https ://edmsbgv.sutherlandglobal.com/Securitas/CRCResult");
                var client = new RestClient(EndPoint);
                client.Timeout = -1;
                var request = new RestRequest(Method.POST);
                //ClientRefId = @""" ClientRefId  """;
                string strClientRefId = @"""" + ClientRefId + "\"";
                string strCompanyRefNo = @"""" + CompanyRefNo + "\"";
                string strColorCode = @"""" + ColorCode + "\"";
                string strstatus = @"""" + status + "\"";
                string sourcefile = "";
                if (reportType != "")
                {
                    sourcefile = ClientRefId + "_CRC_" + reportType + "_" + ColorCode.ToUpper() + ".pdf";
                }
                string strReportName = @"""" + sourcefile + "\"";
                string strVendorComments = @"""" + HTMLToText(VendorComments) + "\"";
                string strCompletionDate = @"""" + CompletionDate + "\"";
                string strInitiatedDate = @"""" + InitiatedDate + "\"";
                string strReportPath = @"""" + ReportPath + "\"";

                var myData = "{\r\n  \"CRCResponse\": [\r\n    {\r\n      \"CandidateId\": " + strClientRefId + ",\r\n      \"VendorCaseId\": " + strCompanyRefNo + ",\r\n      \"Status\":" + strstatus + ",\r\n      \"ColorCode\": " + strColorCode + ",\r\n      \"ReportName\": " + strReportName + ",\r\n      \"ReportPath\": " + strReportPath + ",\r\n      \"InitiatedDate\": " + strInitiatedDate + ",\r\n      \"CompletionDate\": " + strCompletionDate + ",\r\n      \"VendorComments\":  " + strVendorComments + ",\r\n      \"VendorSLA\": \"\"\r\n    }\r\n  ]\r\n}";

                request.AddHeader("IntegrationKey", apiKey);
                request.AddHeader("Content-Type", "application/json");
                request.AddParameter("application/json", myData, ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);
                if (response.StatusCode.ToString() == "OK")
                {
                    InsertAPI_AuditDetail(ClientRefId, 249, "Success", actionType + ":CRC Status", "CompanyRefNo:" + CompanyRefNo + ",ColorCode:" + ColorCode + ",Status:" + status, response.StatusCode.ToString() + ":" + response.Content, "API");
                }
                else
                {
                    InsertAPI_AuditDetail(ClientRefId, 249, "Failed", actionType + ":CRC Status", "CompanyRefNo:" + CompanyRefNo + ",ColorCode:" + ColorCode + ",Status:" + status, response.StatusCode.ToString() + ":" + response.ErrorMessage, "API");
                }
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(ClientRefId, 249, "Failed", actionType + ":CRC Status", "CompanyRefNo:" + CompanyRefNo + ",ColorCode:" + ColorCode + ",Status:" + status, "Exception:" + ex.Message, "API");
            }
        }

