                    if (items.pending_with == "Reviewer" && items.employee_id != "")
                    {//Reviewer
                        DataTable dtId = GetEmp_OfferIdExist(items.unique_id);
                        if (dtId.Rows.Count == 0)
                        {
                            API_Darwinbox_GetCandidateDetails("a62962a3ab14cc", items.unique_id);
                            API_Darwinbox_GetPackage(items.employee_id, items.employee_status, items.unique_id);
                            InsertAPI_AuditDetail(items.unique_id, 931, "Success", "GetCandidateList", items.pending_with, "Successfully loaded all candidate data", "API");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                string error = ex.Message;
                InsertAPI_AuditDetail("", 931, "Failed", "GetCandidateList", "", ex.Message, "API");
            }
        }

        private void API_Darwinbox_GetCandidateDetails(string bgv_id, string unique_id)
