            //dynamic resultData = JsonConvert.DeserializeObject(jsonresult);
            var parsedJson = JObject.Parse(jsonresult);
            var prop = parsedJson["candidate_data"];
            string p = prop.Path;
            JToken item = prop;
            foreach (var element in item)
            {
                //if (item is JArray)
