        private void API_Darwinbox_GetPackage(string employeeId = "", string employee_status = "", string UniqueID = "")
        {   //Vedanta
            DataTable dt = new DataTable();
            dt = GetClientAPIByClientRowId(931, "CandidateList");
            string EndPoint = dt.Rows[0]["EndPoint"].ToString();
            string UName = dt.Rows[0]["UserName"].ToString();
            string psw = dt.Rows[0]["Password"].ToString();
            //string apiKey = dt.Rows[0]["AuthorizationKey"].ToString();
            string apikey = "";
            string datasetKey = "";
            string[] employeeIds = { employeeId };
            if (employee_status.ToLower() == "active")
            {
                apikey = ConfigurationManager.AppSettings["Apikey_active"].ToString();
                datasetKey = ConfigurationManager.AppSettings["DatasetKey_active"].ToString();
            }
            else if (employee_status.ToLower() == "pending")
            {
                apikey = ConfigurationManager.AppSettings["Apikey_pending"].ToString();
                datasetKey = ConfigurationManager.AppSettings["DatasetKey_pending"].ToString();
            }
            try
            {
                var httpWebRequest = (HttpWebRequest)WebRequest.Create(EndPoint);
                httpWebRequest.ContentType = "application/json";
                httpWebRequest.Method = "POST";
                var plainTextBytes = System.Text.Encoding.UTF8.GetBytes(UName + ":" + psw);
                string val = System.Convert.ToBase64String(plainTextBytes);
                httpWebRequest.Headers.Add("Authorization", "Basic " + val);
                using (var streamWriter = new
                StreamWriter(httpWebRequest.GetRequestStream()))
                {
                    string json = new JavaScriptSerializer().Serialize(new
                    {
                        api_key = apikey,
                        datasetKey = datasetKey,
                        employee_ids = employeeIds
                    });
                    streamWriter.Write(json);
                }
                var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse();
                var jsonresult = string.Empty;
                using (var streamReader = new StreamReader(httpResponse.GetResponseStream()))
                {
                    jsonresult = streamReader.ReadToEnd();
                }
                dynamic resultData = JsonConvert.DeserializeObject(jsonresult);
                string status = resultData.status;
                string msg = resultData.message;
                dynamic employee_data = resultData.employee_data;
                string package_name = Convert.ToString(employee_data);
                //string[] edata = employee_data.securitas_package_name;
                insertCaseRegistration("931", "VCAIRN", UniqueID, "Package_Details", "Package", package_name, 931);
            }
            catch (Exception ex)
            {
                string msg = ex.Message;
            }

        }

        public string API_Darwinbox_GetCandidateDocuments(string file_key = "")
        {
            DataTable dt = new DataTable();
            dt = GetClientAPIByClientRowId(931, "CandidateList");
            string EndPoint = dt.Rows[0]["EndPoint"].ToString();
            string UName = dt.Rows[0]["UserName"].ToString();
            string psw = dt.Rows[0]["Password"].ToString();
            string apiKey = dt.Rows[0]["AuthorizationKey"].ToString();
            string[] spplit_file = file_key.Split('_');
            string tempFileName = "";
            for (int i = 0; i < spplit_file.Length; i++)
            {
                if (i > 1)
                {
                    tempFileName = tempFileName + spplit_file[i];
                }
            }
            var httpWebRequest = (HttpWebRequest)WebRequest.Create(EndPoint);
            httpWebRequest.ContentType = "application/json";
            httpWebRequest.Method = "POST";
            var plainTextBytes = System.Text.Encoding.UTF8.GetBytes(UName + ":" + psw);
            string val = System.Convert.ToBase64String(plainTextBytes);
            httpWebRequest.Headers.Add("Authorization", "Basic " + val);
            using (var streamWriter = new
            StreamWriter(httpWebRequest.GetRequestStream()))
            {
                string json = new JavaScriptSerializer().Serialize(new
                {
                    api_key = apiKey,
                    file_key = file_key
                });
                streamWriter.Write(json);
            }
            var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse();
            var jsonresult = string.Empty;
            using (var streamReader = new StreamReader(httpResponse.GetResponseStream()))
            {
                jsonresult = streamReader.ReadToEnd();
            }
            dynamic resultData = JsonConvert.DeserializeObject(jsonresult);
            string status = resultData.status;
            string msg = resultData.message;
            string file = resultData.file;
            string fileName = DateTime.Now.ToString("ddMMyyyy") + "-" + tempFileName;
            string filePath = System.Web.HttpContext.Current.Server.MapPath("~/documents/") + fileName;
            //string saveLocation = HttpServer.MapPath("~/documents/whatever2.png");
            File.WriteAllBytes(filePath, Convert.FromBase64String(file));
            return fileName;

        }

        public void convertbase64topdf(string base64, string fileName)
        {
            string filePath = System.Web.HttpContext.Current.Server.MapPath("~/documents/") + DateTime.Now.ToString("ddMMyyyy") + "-" + fileName;
            //string saveLocation = HttpServer.MapPath("~/documents/whatever2.png");
            File.WriteAllBytes(filePath, Convert.FromBase64String(base64));
        }

        public List<Darwinbox_Candidate_data> GetAPI_Darwinbox_Candidate_data(string UniqueID = "")
        {
            try
            {

                DataTable dt = new DataTable();
                Darwinbox_Candidate_data model = new Darwinbox_Candidate_data();

                dt = GetAPICandidateList(UniqueID);

                List<Darwinbox_Candidate_data> lmd = new List<Darwinbox_Candidate_data>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        Darwinbox_Candidate_data mm = new Darwinbox_Candidate_data();
                        mm.unique_id = dr["unique_id"].ToString();
                        mm.candidate_id = dr["candidate_id"].ToString();
                        mm.employee_id = dr["employee_id"].ToString();
                        mm.candidate_name = (dr["candidate_name"]).ToString();
                        mm.employee_status = (dr["employee_status"]).ToString();
                        mm.bgv_status = (dr["bgv_status"]).ToString();
                        mm.pending_with = (dr["pending_with"]).ToString();
                        mm.application_form_submitted_on = dr["application_form_submitted_on"].ToString();
                        mm.application_form_created_on = dr["application_form_created_on"].ToString();
                        mm.application_form_updated_on = dr["application_form_updated_on"].ToString();
                        mm.date_of_activation = dr["date_of_activation"].ToString();
                        mm.status = dr["Status"].ToString();
                        //mm.CreatedOn = dr["CreatedOn"].ToString();
                        lmd.Add(mm);
                    }

                    //model.TotalRecords = dt.Rows.Count;
                    //model.APICandidateSummaryDetail = lmd;
                }
                //else
                //{
                //    model.TotalRecords = 0;
                //}

                return lmd;
            }
            catch (Exception ex)
            {
                throw;
                //string msg = ex.Message;
            }
        }

