        private string CventReportStatus(string customerId, string personId, string cventStatusID, string cventStatusValue, string BGVCompletedDate, string reportURL, string actionType)
        {
            string apiResponseCode = "";
            try
            {
                DataTable dt = new DataTable();
                dt = GetClientAPIByClientRowId(8, "BGVReport");
                //string EndPoint = dt.Rows[0]["EndPoint"].ToString();
                string UName = dt.Rows[0]["UserName"].ToString();
                string psw = dt.Rows[0]["Password"].ToString();
                CventAPIStatus bgcorderstatus = new CventAPIStatus { id = cventStatusID, value = cventStatusValue };
                string url = "https://api.icims.com/customers/" + customerId + "/people/" + personId + "/fields/bgcresults";
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "POST";
                request.ContentType = "application/json";
                var plainTextBytes = System.Text.Encoding.UTF8.GetBytes(UName + ":" + psw);
                string val = System.Convert.ToBase64String(plainTextBytes);
                request.Headers.Add("Authorization", "Basic " + val);
                string json = "";
                using (var streamWriter = new
                StreamWriter(request.GetRequestStream()))
                {
                    json = new JavaScriptSerializer().Serialize(new
                    {
                        bgcorderstatus = bgcorderstatus,
                        bgcurl = reportURL,
                        bgccompleteddate = BGVCompletedDate
                    });
                    streamWriter.Write(json);
                }
                var httpResponse = (HttpWebResponse)request.GetResponse();
                apiResponseCode = httpResponse.StatusCode.ToString();
                if (apiResponseCode == "Created")
                {
                    InsertAPI_AuditDetail(personId, 8, "Success", actionType, json, apiResponseCode, "API");
                }
                else
                {
                    InsertAPI_AuditDetail(personId, 8, "Failed", actionType, json, apiResponseCode + ",Error:" + httpResponse.StatusDescription, "API");
                }
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(personId, 8, "Failed", actionType, "CustomerId:" + customerId + ",StatusId:" + cventStatusID + ",StatusValue:" + cventStatusValue + ",BGVCompletedDate:" + BGVCompletedDate + ",ReportURL:" + reportURL, "Exception:" + ex.Message, "API");
            }
            return apiResponseCode;
        }
