        public static Token GetAccessToken()
        {
            Token token = new Token();
            try
            {
                DataBaseConnections Dc = new DataBaseConnections();
                string Email = "";
                string Password = "";

                var ClientAuth = Dc.SP_GetClientAPIDetails(270, "Basic", "AccessToken");
                if (ClientAuth.Rows.Count > 0)
                {
                    Email = Convert.ToString(ClientAuth.Rows[0]["UserName"]);
                    Password = Convert.ToString(ClientAuth.Rows[0]["Password"]);
                }

                string response = "";
                string strURL = "https://api.walsonsverify.com/validate-user";
                string jsonString = "{\"Email\":\"" + Email + "\",\"Password\":\"" + Password + "\"}";
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(strURL);
                request.Method = "POST";
                request.ContentType = "application/json";
                request.ContentLength = jsonString.Length;
                StreamWriter requestWriter = new StreamWriter(request.GetRequestStream(), System.Text.Encoding.ASCII);
                requestWriter.Write(jsonString);
                requestWriter.Close();

                WebResponse webResponse = request.GetResponse();
                Stream webStream = webResponse.GetResponseStream();
                StreamReader responseReader = new StreamReader(webStream);
                response = responseReader.ReadToEnd();
                B2CModelClass.Rootobject gettoken = JsonConvert.DeserializeObject<B2CModelClass.Rootobject>(response);
                token.access_token = gettoken.Data.Token.ToString();
                //int count = gettoken.Data.Token;
                //List<Data> data_list = new List<Data>();
                //token.access_token = data_list[0].Token.ToString();

            }
            catch (Exception ex)
            {

            }
            return token;
        }

        public void SendCandidateReport(string Clientrefid, int clientRowId, string OrderId, string Report_uploaded_date, string Date, string File_Value, string File_name, string ColorCode, string Remarks, string Report_Status, string version_no, int personalRowId)
        {
            string jsonString = "";
            try
            {
                string response = "";
                Token token = GetAccessToken();
                string Authorization = "";
                var ClientAuth = Dc.SP_GetClientAPIDetails(270, "Basic", "AccessToken");
                if (ClientAuth.Rows.Count > 0)
                {
                    Authorization = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]);
                }
                string strURL = "https://api.walsonsverify.com/AddManualReport";
                jsonString = "{\"Order_id\":\"" + OrderId + "\",\"Report_uploaded_date\":\"" + Report_uploaded_date.Replace("/", "-") + "\",\"Date\":\"" + Report_uploaded_date + "\",\"File_Value\":\"" + File_Value + "\",\"File_name\":\"" + File_name + "\",\"ColorCode\":\"" + ColorCode + "\",\"Remarks\":\"" + Remarks + "\",\"Report_Status\":\"" + Report_Status + "\",\"version_no\":\"" + version_no + "\"}";
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(strURL);
                request.Method = "POST";
                request.ContentType = "application/json";
                request.Headers.Add("Authorization", Authorization);
                request.Headers.Add("token", token.access_token);
                request.ContentLength = jsonString.Length;

                StreamWriter requestWriter = new StreamWriter(request.GetRequestStream(), System.Text.Encoding.ASCII);
                requestWriter.Write(jsonString);
                requestWriter.Close();
                StrBuilderObj.Append(jsonString.ToString());

                WebResponse webResponse = request.GetResponse();
                Stream webStream = webResponse.GetResponseStream();
                StreamReader responseReader = new StreamReader(webStream);
                response = responseReader.ReadToEnd();
                //B2CModelClass.Rootobject GetDetails = JsonConvert.DeserializeObject<B2CModelClass.Rootobject>(response);
                if (response.Contains("Recrord fetch Successfully"))
                {
                    InsertAPI_AuditDetail(Clientrefid, clientRowId, "Success", "B2CReportStatus", "RequestData:" + response.ToString(), response, "API");
                    //StrBuilderObj.Append(Environment.NewLine);
                    //StrBuilderObj.Append("----------------------------API Response-----------------");
                    //StrBuilderObj.Append(Environment.NewLine);
                    //StrBuilderObj.Append("Response:Success  DataType:LTIMindtreeReport");
                    //WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "SendStatusAndReport", clientRowId + "-" + personalRowId + "-Success");

                }
                else
                {
                    InsertAPI_AuditDetail(Clientrefid, clientRowId, "Failed", "B2CReportStatus", "RequestData:" + response.ToString(), response, "API");
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("----------------------------API Response-----------------");
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("Response:Failed  DataType:BGVStatus");
                    WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "SendStatusAndReport", clientRowId + "-" + personalRowId + "-Failed");

                }
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(Clientrefid, clientRowId, "Failed", "B2CReportStatus", "RequestData:" + "", ex.Message.ToString(), "API");
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("----------------------------API Response-----------------");
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("Response:Failed  DataType:BGVStatus  " + "Exception:" + ex.Message.ToString());
                WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "SendStatusAndReport", clientRowId + "-" + personalRowId + "-Exception-Failed");


            }
        }
