                var result1 = response.Result.Content;
                if (result1.Contains("Get all document cases list Details Successfully"))
                {
                    API.RootobjectDocRep myDeserializedClass = JsonConvert.DeserializeObject<API.RootobjectDocRep>(result1);
                    foreach (var item2 in myDeserializedClass.Property1)
