        public static string Convertbase64Files(string fileName, string Base64Values, string Qtype)
        {
            string res = "";
            try
            {
                string filePath = "";
                if (Qtype == "document")
                {
                    filePath = System.Web.HttpContext.Current.Server.MapPath("~/Documents/CandidateDocuments/ProvidedDocuments/" + fileName);
                }
                else if (Qtype == "report")
                {
                    filePath = System.Web.HttpContext.Current.Server.MapPath("~/Documents/CandidateReport/" + fileName);
                }
                byte[] fileBytes = Convert.FromBase64String(Base64Values);
                File.WriteAllBytes(filePath, fileBytes);
                res = "Get all document cases list Details Successfully";
            }
            catch (Exception ex)
            {
                res = ex.Message.ToString();
            }
            return res;

        }
