        #region  ETS Client API
        public void Send_Status_ETS_API(int clientRowId, string ReferenceId, string OrderId, string Url, string data, string Status)
        {
            string result = "";
            string xmlData = "";
            try
            {
                try
                {
                    Getdata_API(clientRowId, ReferenceId, OrderId);
                }
                catch (Exception ex)
                {
                }
                string url = "https://www.pereless.com/ff/api/securitas/callback.cfm";
                string boundary = "---------------------------" + DateTime.Now.Ticks.ToString("x");
                xmlData = "<?xml version=\"1.0\"?>" +
                   "<BackgroundReports userId=\"\" password=\"\" databaseset=\"\">" +
                   "<BackgroundReportPackage>" +
                   "<ReferenceId><![CDATA[" + ReferenceId + "]]></ReferenceId>" +
                   "<OrderId>" + OrderId + "</OrderId>" +
                   "<ScreeningStatus>" +
                   "<OrderStatus flag=\"FALSE\">x:" + Status + "</OrderStatus>" +
                   "<OrderDecision>-</OrderDecision>" +
                   "</ScreeningStatus>" +
                   "<Screenings>" +
                   "<Screening type=\"criminal\" qualifier=\"county\">" +
                   "<ScreeningResults type=\"result\" mediaType=\"html\" resultType=\"report\">" +
                   "<InternetWebAddress><![CDATA[" + " " + Url + " " + "]]></InternetWebAddress>" +
                   "</ScreeningResults>" +
                   "</Screening>" +
                   "</Screenings>" +
                   "</BackgroundReportPackage>" +
                   "</BackgroundReports>";
                StringBuilder sb = new StringBuilder();
                sb.AppendLine("--" + boundary);
                sb.AppendLine("Content-Disposition: form-data; name=\"STATUS\"");
                sb.AppendLine("Content-Type: text/xml; charset=utf-8");
                sb.AppendLine();
                sb.AppendLine(xmlData);
                sb.AppendLine("--" + boundary + "--");
                byte[] postBytes = Encoding.UTF8.GetBytes(sb.ToString());
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "POST";
                request.ContentType = "multipart/form-data; boundary=" + boundary;
                request.ContentLength = postBytes.Length;
                request.KeepAlive = true;
                request.Timeout = 30000;
                using (Stream requestStream = request.GetRequestStream())
                {
                    requestStream.Write(postBytes, 0, postBytes.Length);
                }

                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                {
                    using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                    {
                        result = reader.ReadToEnd();
                        if (result.Contains("Candidate Information Updated.") || result.Contains("200"))
                        {
                            InsertAPI_AuditDetail(ReferenceId, clientRowId, "Success", Status, xmlData, result, "API");
                        }
                        else
                        {
                            InsertAPI_AuditDetail(ReferenceId, clientRowId, "Failed", Status, xmlData, result, "API");
                            //}
                        }
                    }

                }
            }
            catch (Exception ex)
            {
                InsertAPI_AuditDetail(ReferenceId, clientRowId, "Failed", Status, xmlData, "Exception:" + ex.Message + "," + result, "API");

            }

        }
