        public static string CheckLivelinessStatus_API(string id, string requestId)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            string result = "";
            try
            {
                DataBaseConnections Dc = new DataBaseConnections();
                string clientId = "";
                string clientSecret = "";
                var ClientAuth = Dc.SP_GetClientAPIDetails(274, "clientSecret", "Liveliness");
                if (ClientAuth.Rows.Count > 0)
                {
                    clientId = Convert.ToString(ClientAuth.Rows[0]["UserName"]);
                    clientSecret = Convert.ToString(ClientAuth.Rows[0]["Password"]);
                }
                string strURL = "https://sm-kyc-sync-prod.scoreme.in/kyc/external/checkLivelinessStatus";
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(strURL);
                request.Method = "POST";
                request.ContentType = "application/json";
                request.Headers.Add("clientId", clientId);
                request.Headers.Add("clientSecret", clientSecret);
                JavaScriptSerializer serializer = new JavaScriptSerializer();
                serializer.MaxJsonLength = Int32.MaxValue;
                StrBuilderObj.Append("----------------------------strURL-----------------" + strURL);
                StrBuilderObj.Append(Environment.NewLine);
                string json = "";
                using (var streamWriter = new
                StreamWriter(request.GetRequestStream()))
                {
                    json = "{\"requestId\":\"" + requestId + "\"}";
                    streamWriter.Write(json);
                }
                StrBuilderObj.Append("----------------------------Request-----------------" + json);
                StrBuilderObj.Append(Environment.NewLine);
                int Machingperc = 0;
                var httpResponse = (HttpWebResponse)request.GetResponse();
                using (var streamReader = new StreamReader(httpResponse.GetResponseStream()))
                {
                    result = streamReader.ReadToEnd();
                    StrBuilderObj.Append("----------------------------result-----------------" + result);
                    StrBuilderObj.Append(Environment.NewLine);
                    RootobjectStatus objStatus = JsonConvert.DeserializeObject<RootobjectStatus>(result);
                    if (result.Contains("completed") || result.Contains("Completed"))
                    {
                        Machingperc = Convert.ToInt32(objStatus.data.facialMatchPercentage);
                        UpdateLivelinessStatusUserDetails(Convert.ToInt32(id), Machingperc, Convert.ToString(objStatus.responseMessage), "update");
                        //WriteLog(StrBuilderObj.ToString(), "", "", "InitiateLiveliness_API", "CheckLivelinessStatus", id + System.DateTime.Now.ToString("-dd-MM-yyyy-hh-mm-ss") + "-Success");

                    }
                    else
                    {
                        string Resmsg = objStatus.responseMessage.ToString();
                        UpdateLivelinessStatusUserDetails(Convert.ToInt32(id), Machingperc, Resmsg, "update");
                        result = Resmsg;
                        WriteLog(StrBuilderObj.ToString(), "", "", "InitiateLiveliness_API", "CheckLivelinessStatus", id + System.DateTime.Now.ToString("-dd-MM-yyyy-hh-mm-ss") + "-Failed");
                    }
                }
            }
            catch (Exception ex)
            {
                string Resmsg = ex.Message.ToString();
                UpdateLivelinessStatusUserDetails(Convert.ToInt32(id), 0, "Exception:-" + Resmsg, "update");
                result = Resmsg;
                StrBuilderObj.Append("----------------------------Exception-----------------" + Resmsg);
                StrBuilderObj.Append(Environment.NewLine);
                WriteLog(StrBuilderObj.ToString(), "", "", "InitiateLiveliness_API", "CheckLivelinessStatus", id + System.DateTime.Now.ToString("-dd-MM-yyyy-hh-mm-ss") + "-Exception");
            }
            return result;
        }

