        public string GetZinniaToken(int personalRowID)
        {
            try
            {
                var request = new HttpRequestMessage(HttpMethod.Post, "https://api.zinnia.io/api/v1/integrations/securitas/oauth2/token");

                // Build Basic Auth header dynamically
                //string clientId = "securitas-test";
                //string clientSecret = "9df221ea737f7abc6e2607f52eccec221962c1fd4f4a47940bd8d56a657b503e";
                string clientId = "securitas-webhooks";
                string clientSecret = "cccaead2120aecb3e67bead5a3f1b89ad0bb16f8c5abe6d4038c1ee1cbe681c5";
                string credentials = $"{clientId}:{clientSecret}";
                string base64Credentials = Convert.ToBase64String(Encoding.ASCII.GetBytes(credentials));

                request.Headers.Authorization = new AuthenticationHeaderValue("Basic", base64Credentials);
                request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));

                // Add body (form-url-encoded)
                request.Content = new FormUrlEncodedContent(new[] { new KeyValuePair<string, string>("grant_type", "client_credentials") });

                using (HttpClient _httpClient = new HttpClient())
                {
                    var response = _httpClient.SendAsync(request).GetAwaiter().GetResult();
                    response.EnsureSuccessStatusCode();
                    string responseBody = response.Content.ReadAsStringAsync().GetAwaiter().GetResult();
                    ZinniaToken tokenResponse = JsonConvert.DeserializeObject<ZinniaToken>(responseBody);
                    return tokenResponse.access_token;
                }
            }
            catch (Exception ex)
            {
                // Log the exception
                string res = ex.Message;
                StrBuilderObj.Append("----------------------------Exception-----------------" + res);
                StrBuilderObj.Append(Environment.NewLine);
                WriteLog(StrBuilderObj.ToString(), "", "", "GetZinniaToken_API", "GetZinniaToken", personalRowID + System.DateTime.Now.ToString("-dd-MM-yyyy-hh-mm-ss") + "-Exception");
                // Return a safe fallback
                return string.Empty;
            }
        }
