        #region Microsoft Azure sso login       
        public static string Microsoft_Azure_ssoAPI(string client_id, string client_secret, string tenantId, string code, string redirect_uri)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            StrBuilderObj.Clear();
            string Token = "";
            string Url = "https://login.microsoftonline.com/" + tenantId + "/oauth2/v2.0/token";
            var request = (HttpWebRequest)WebRequest.Create(Url);
            request.Method = "POST";
            request.ContentType = "application/x-www-form-urlencoded";

            string postData = "grant_type=authorization_code" +
                              "&client_id=" + client_id +
                              "&client_secret=" + client_secret +
                              "&code=" + code + // Truncated for clarity
                              "&redirect_uri=" + redirect_uri;

            byte[] byteArray = Encoding.UTF8.GetBytes(postData);

            using (Stream dataStream = request.GetRequestStream())
            {
                dataStream.Write(byteArray, 0, byteArray.Length);
            }

            try
            {
                using (WebResponse response = request.GetResponse())
                {
                    using (Stream responseStream = response.GetResponseStream())
                    {
                        StreamReader reader = new StreamReader(responseStream);
                        string responseText = reader.ReadToEnd();
                        JwtToken token = JsonConvert.DeserializeObject<JwtToken>(responseText);
                        Token = Convert.ToString(token.access_token);


                    }
                }
            }
            catch (WebException ex)
            {
                using (var stream = ex.Response.GetResponseStream())
                {
                    StreamReader reader = new StreamReader(stream);
                    string errorResponse = reader.ReadToEnd();
                }
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("Response:Exception" + ex.Message.ToString());
                WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "Microsoft_Azure_ssoAPI", "" + "-" + "" + "-Exception-" + System.DateTime.Now.ToString("dd-MM-yyyy-hh-mm-ss"));

            }
            return Token;
        }

        public static UserModel Jwttoken(string jwtToken)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            var userModel = new UserModel();

            try
            {
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("jwtToken:- " + jwtToken);

                var handler = new JwtSecurityTokenHandler();
                var token = handler.ReadJwtToken(jwtToken);
                //foreach (var kvp in token.Header)
                //{
                //    Console.WriteLine($"{kvp.Key}: {kvp.Value}");
                //}
                foreach (var claim in token.Claims)
                {
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("token.Claims:- " + token.Claims);

                    var claimType = claim.Type.ToLower().Trim();
                    var value = claim.Value;

                    switch (claimType)
                    {
                        case "name":
                            userModel.Name = value;
                            break;
                        case "unique_name":
                            userModel.UniqueName = value;
                            break;
                        case "upn":
                            userModel.UPN = value;
                            break;
                    }
                }
            }
            catch (Exception ex)
            {
                StrBuilderObj.Append(Environment.NewLine);
                StrBuilderObj.Append("Response:Exception" + ex.Message.ToString());
                WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "Jwttoken", "" + "-" + "" + "-Exception-" + System.DateTime.Now.ToString("dd-MM-yyyy-hh-mm-ss"));

            }
            return userModel;
        }

        public class UserModel
        {
            public string Name { get; set; }
            public string UniqueName { get; set; }
            public string UPN { get; set; }
        }

        public class JwtToken
        {
            public string token_type { get; set; }
            public string scope { get; set; }
            public int expires_in { get; set; }
            public int ext_expires_in { get; set; }
            public string access_token { get; set; }
            public string id_token { get; set; }
        }

