        #region Current Addreass Veri API weverifyglobal
        public static string Current_Addreass_Veri_API(string name, string address_type, string mobile, string email, string address, string reference_number)
        {
            string res = "";
            string Api_Key = "";
            DataBaseConnections Dc = new DataBaseConnections();
            var ClientAuth = Dc.SP_GetClientAPIDetails(274, "clientSecret", "Liveliness");
            if (ClientAuth.Rows.Count > 0)
            {
                Api_Key = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]);
            }

            string url = "https://dgbgvapi.weverifyglobal.com/api/job/";
            string boundary = "------------------------" + DateTime.Now.Ticks.ToString("x");
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "POST";
            request.ContentType = "multipart/form-data; boundary=" + boundary;
            request.Headers.Add("Authorization", Api_Key);
            // Form data
            var formData = new StringBuilder();
            AddFormData(formData, boundary, "name", name);
            AddFormData(formData, boundary, "address_type", address_type);
            AddFormData(formData, boundary, "mobile", mobile);
            AddFormData(formData, boundary, "email", email);
            AddFormData(formData, boundary, "address", address);
            AddFormData(formData, boundary, "job_status", "open");
            AddFormData(formData, boundary, "reference_number", reference_number);
            AddFormData(formData, boundary, "inv_type", "1");
            AddFormData(formData, boundary, "verifier_number", "9871322960");
            AddFormData(formData, boundary, "reference_type", "TREF");
            formData.Append("--" + boundary + "--\r\n");
            byte[] formBytes = Encoding.UTF8.GetBytes(formData.ToString());
            request.ContentLength = formBytes.Length;
            using (Stream requestStream = request.GetRequestStream())
            {
                requestStream.Write(formBytes, 0, formBytes.Length);
            }

            try
            {
                using (WebResponse response = request.GetResponse())
                using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                {
                    res = reader.ReadToEnd();
                }
            }
            catch (WebException ex)
            {
                using (StreamReader reader = new StreamReader(ex.Response.GetResponseStream()))
                {
                    res = reader.ReadToEnd();
                }
            }
            return res;
        }
