        private static void AddFormData(StringBuilder formData, string boundary, string name, string value)
        {
            formData.AppendLine($"--{boundary}");
            formData.AppendLine($"Content-Disposition: form-data; name=\"{name}\"");
            formData.AppendLine(); // Blank line required between headers and content
            formData.AppendLine(value);
        }

