        public async Task<ZipCodeData> GetZipCodeDataAsync(string countryCode, string pinCode)
        {
            using (HttpClient client = new HttpClient())
            {
                string url = $"http://api.zippopotam.us/{countryCode}/{pinCode}";
                HttpResponseMessage response = await client.GetAsync(url);

                if (response.IsSuccessStatusCode)
                {
                    string jsonString = await response.Content.ReadAsStringAsync();
                    var result = JsonConvert.DeserializeObject<ZipCodeData>(jsonString);
                    return result;
                }
                else
                {
                    return null;
                }
            }
