                var ClientAuth = Dc.SP_GetClientAPIDetails(Convert.ToInt32(clientRowId), "Basic", "GetToken");
                if (ClientAuth.Rows.Count > 0)
                {
                    username = Convert.ToString(ClientAuth.Rows[0]["UserName"]).Trim();
                    Password = Convert.ToString(ClientAuth.Rows[0]["Password"]).Trim();
                }                                                                                   // Your payload
                var payload = new
                {
                    username = username,
                    password = Password,
                    email = "",
                    device_os = "web",
                    device_token = "a"
                };

                string jsonPayload = JsonConvert.SerializeObject(payload);

                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "POST";
                request.ContentType = "application/json";
                // Write payload to request stream
                using (var streamWriter = new StreamWriter(request.GetRequestStream()))
                {
                    streamWriter.Write(jsonPayload);
                }

                try
                {
                    using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                    {
                        using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                        {
                            string resp = reader.ReadToEnd();
                            dynamic data = JsonConvert.DeserializeObject<dynamic>(resp);
                            result = resp;
                            JObject obj = JObject.Parse(resp);

                            // Get access token
                            result = (string)obj["access"];
                            var res = Dc.sp_SaveTokenDetails(clientRowId, result);

                        }
                    }
                }
                catch (WebException ex)
                {
                    using (StreamReader reader = new StreamReader(ex.Response.GetResponseStream()))
                    {
                        string errorText = reader.ReadToEnd();
                        Console.WriteLine("Error:");
                        Console.WriteLine(errorText);
                    }
                }
            }
            return result;
        }
