        public string Report_Pushed_Details(string employeesId, string clientRowId, string DocmentName, string documenttypes, string ColCode, string remark, string RquestData)
        {
            string Result = "";
            string bgvStatus = "";
            string url = "https://neysa.keka.com/api/v1/hris/employees/" + employeesId + "/documenttypes/" + documenttypes;
            var json = GetTokenNeysa(clientRowId);
            JObject obj = JObject.Parse(json);
            // Get access token
            string accessToken = (string)obj["access_token"];
            string filePath = System.Web.HttpContext.Current.Server.MapPath("~/Documents/CandidateReport/" + DocmentName);
            byte[] fileData = File.ReadAllBytes(filePath);
            string boundary = "----WebKitFormBoundary" + DateTime.Now.Ticks.ToString("x");
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "POST";
            request.ContentType = "multipart/form-data; boundary=" + boundary;
            request.Headers.Add("Authorization", "Bearer " + accessToken);

            using (Stream requestStream = request.GetRequestStream())
            {
                // Add form fields
                string formDataTemplate = "--{0}\r\nContent-Disposition: form-data; name=\"{1}\"\r\n\r\n{2}\r\n";
                string formItem1 = string.Format(formDataTemplate, boundary, documenttypes + "-status", ColCode);
                string formItem2 = string.Format(formDataTemplate, boundary, documenttypes + "-remark", remark);

                byte[] formItemBytes1 = Encoding.UTF8.GetBytes(formItem1);
                byte[] formItemBytes2 = Encoding.UTF8.GetBytes(formItem2);

                requestStream.Write(formItemBytes1, 0, formItemBytes1.Length);
                requestStream.Write(formItemBytes2, 0, formItemBytes2.Length);

                // Add file
                string fileHeader = $"--{boundary}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"{DocmentName}\"\r\nContent-Type: application/pdf\r\n\r\n"; byte[] fileHeaderBytes = Encoding.UTF8.GetBytes(fileHeader);
                requestStream.Write(fileHeaderBytes, 0, fileHeaderBytes.Length);
                requestStream.Write(fileData, 0, fileData.Length);

                // End boundary
                byte[] endBoundaryBytes = Encoding.UTF8.GetBytes($"\r\n--{boundary}--\r\n");
                requestStream.Write(endBoundaryBytes, 0, endBoundaryBytes.Length);
            }
            try
            {

                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                {
                    string responseText = reader.ReadToEnd();
                    Result = responseText;
                    if (responseText.Contains("true"))
                    {
                        InsertAPI_AuditDetail_LTI(employeesId, Convert.ToInt32(clientRowId), "Success", bgvStatus, "VenderReferenceId:" + DocmentName + ",Colorcode:" + ColCode + ",ReportType:" + DocmentName, responseText, "API", 0);

                    }
                    else
                    {
                        InsertAPI_AuditDetail_LTI(employeesId, Convert.ToInt32(clientRowId), "Failed", bgvStatus, "VenderReferenceId:" + DocmentName + ",Colorcode:" + ColCode + ",ReportType:" + DocmentName, responseText, "API", 0);
                    }
                }

            }
            catch (WebException ex)
            {
                using (StreamReader reader = new StreamReader(ex.Response.GetResponseStream()))
                {
                    Result = reader.ReadToEnd();
                }
                InsertAPI_AuditDetail_LTI(employeesId, Convert.ToInt32(clientRowId), "Failed", bgvStatus, "VenderReferenceId:" + DocmentName + ",Colorcode:" + ColCode + ",ReportType:" + DocmentName, Result, "API", 0);

            }

            return Result;
        }
        public string GetTokenNeysa(string clientRowId)
        {
            string Result = "";
            string url = "https://login.keka.com/connect/token";
            string client_id = "";
            string client_secret = "";
            string api_key = "";
            var ClientAuth = Dc.SP_GetClientAPIDetails(Convert.ToInt32(clientRowId), "Basic", "GetToken");
            if (ClientAuth.Rows.Count > 0)
            {
                client_id = Convert.ToString(ClientAuth.Rows[0]["UserName"]).Trim();
                client_secret = Convert.ToString(ClientAuth.Rows[0]["Password"]).Trim();
                api_key = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]).Trim();
            }
            // Build the POST body (application/x-www-form-urlencoded)
            string postData = "grant_type=kekaapi" +
                              "&scope=kekaapi" +
                              "&client_id=" + client_id +
                              "&client_secret=" + client_secret +
                              "&api_key=" + api_key;

            byte[] dataBytes = Encoding.UTF8.GetBytes(postData);

            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "POST";
            request.ContentType = "application/x-www-form-urlencoded";
            request.ContentLength = dataBytes.Length;

            // Optional: set cookie header if required
            request.Headers["Cookie"] = "TiPMix=0.8898369087272262; x-ms-routing-name=self";

            // Write POST data
            using (Stream requestStream = request.GetRequestStream())
            {
                requestStream.Write(dataBytes, 0, dataBytes.Length);
            }

            try
            {
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                {
                    Result = reader.ReadToEnd();
                    Console.WriteLine("Response:");
                    Console.WriteLine(Result);
                }
            }
            catch (WebException ex)
            {
                using (StreamReader reader = new StreamReader(ex.Response.GetResponseStream()))
                {
                    Result = reader.ReadToEnd();
                    Console.WriteLine("Error:");
                    Console.WriteLine(Result);
                }

            }
            return Result;
        }

