        public string PutBackgroundCheck(string unique_id, int clientRowId, int SubCheckRowID, string eventWid, string statusId, string statusComment, string packageId, string resultsUrl, string packageComment, string testId, string statusDate)
        {
            string url = "https://wd3-services1.myworkday.com/ccx/service/diconium/Recruiting/v46.0";
            string soapXml = $@"<?xml version=""1.0"" encoding=""UTF-8""?>
<env:Envelope
  xmlns:env=""http://schemas.xmlsoap.org/soap/envelope/""
  xmlns:xsd=""http://www.w3.org/2001/XMLSchema""
  xmlns:wsse=""http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd""
  xmlns:bsvc=""urn:com.workday/bsvc"">
  <env:Body>
    <wd:Put_Background_Check_Request xmlns:wd=""urn:com.workday/bsvc"" wd:version=""v45.1"">
      <wd:Background_Check_Data>
        <wd:Event_Reference>
          <wd:ID wd:type=""WID"">{eventWid}</wd:ID>
        </wd:Event_Reference>

        <wd:Background_Check_Status_Data>
          <wd:Status_Date>{statusDate}</wd:Status_Date>
          <wd:Status_Reference>
            <wd:ID wd:type=""Background_Check_Status_ID"">{statusId}</wd:ID>
          </wd:Status_Reference>
          <wd:Status_Comment>{statusComment}</wd:Status_Comment>
        </wd:Background_Check_Status_Data>

        <wd:Package_Reference_Data>
          <wd:Package_Reference>
            <wd:ID wd:type=""Background_Check_Package_ID"">{packageId}</wd:ID>
          </wd:Package_Reference>
          <wd:Status_Reference>
            <wd:ID wd:type=""Background_Check_Status_ID"">{statusId}</wd:ID>
          </wd:Status_Reference>
          <wd:Results_URL>{resultsUrl}</wd:Results_URL>
          <wd:Package_Comment>{packageComment}</wd:Package_Comment>
        </wd:Package_Reference_Data>

        <wd:Test_Reference_Data>
          <wd:Background_Check_Package_Test_Reference>
            <wd:ID wd:type=""Background_Check_Package_Test_ID"">{testId}</wd:ID>
          </wd:Background_Check_Package_Test_Reference>
          <wd:Status_Reference>
            <wd:ID wd:type=""Background_Check_Status_ID"">{statusId}</wd:ID>
          </wd:Status_Reference>
        </wd:Test_Reference_Data>
      </wd:Background_Check_Data>
    </wd:Put_Background_Check_Request>
  </env:Body>
</env:Envelope>";
            // Optional: ensure TLS 1.2+ (Workday requires modern TLS)
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls11
                                                 | SecurityProtocolType.Tls12; // TLS 1.3 if supported
            var request = (HttpWebRequest)WebRequest.Create(url);
            string Token = GetTokenDetails(clientRowId);
            // Add Authorization header
            request.Headers["Authorization"] = "Bearer " + Token;
            request.Method = "POST";
            request.ContentType = "text/xml; charset=utf-8";   // SOAP uses text/xml
            request.Headers.Add("SOAPAction", "");             // Workday usually ignores SOAPAction; empty is fine
            request.Timeout = 100_000;                         // 100 seconds; adjust as needed
            request.KeepAlive = true;

            // Write SOAP XML into the request stream
            byte[] payloadBytes = Encoding.UTF8.GetBytes(soapXml);
            request.ContentLength = payloadBytes.Length;
            using (var reqStream = request.GetRequestStream())
            {
                reqStream.Write(payloadBytes, 0, payloadBytes.Length);
            }

            // Read response (success or SOAP Fault)
            try
            {
                using (var response = (HttpWebResponse)request.GetResponse())
                using (var reader = new StreamReader(response.GetResponseStream()))
                {
                    string result = reader.ReadToEnd();
                    if (response.StatusCode.ToString() == "OK")
                    {
                        InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Success", "BgvStatus:" + statusId, "RequestData:" + soapXml, result, "API", SubCheckRowID);
                    }
                    else
                    {
                        InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", "BgvStatus:" + statusId, "RequestData:" + soapXml, result, "API", SubCheckRowID);

                    }
                    return result;
                }
            }
            catch (WebException ex)
            {
                string errorDetails = "";
                if (ex.Response != null)
                {
                    using (var resp = (HttpWebResponse)ex.Response)
                    using (var reader = new StreamReader(resp.GetResponseStream()))
                    {
                        errorDetails = reader.ReadToEnd();
                        InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", "BgvStatus:" + statusId, "RequestData:" + soapXml, errorDetails, "API", SubCheckRowID);
                    }
                }
                else
                {
                    Console.Error.WriteLine("WebException: " + ex.Message);
                }

                // Bubble up the fault body for debugging/logging
                return errorDetails;
            }
        }
        public string PutBackgroundReport(string unique_id, int clientRowId, string attachmentId, string filename, string base64File, string comment, string RequestData)
        {
            string errorDetails = "";
            var url = "https://wd3-services1.myworkday.com/ccx/service/diconium/Staffing/v46.0";
            string candidateId = unique_id;
            //string attachmentId = DateTime.Now.ToString("yyyyMMddHHmmss");
            //string filename = "Test_Final_Report.pdf";
            //string base64File = ""; // e.g., convert from a PDF file
            string contentType = "application/pdf";
            //string comment = "abcdef";
            string documentCategory = "BACKGROUND CHECK"; // this must match your tenant’s category
            string soapXml = $@"<?xml version=""1.0"" encoding=""UTF-8""?>
<env:Envelope xmlns:env=""http://schemas.xmlsoap.org/soap/envelope/""
    xmlns:xsd=""http://www.w3.org/2001/XMLSchema""
    xmlns:wsse=""http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd""
    xmlns:bsvc=""urn:com.workday/bsvc"">
  <env:Body>
    <wd:Put_Candidate_Attachment_Request xmlns:wd=""urn:com.workday/bsvc"" wd:Add_Only=""true"" wd:version=""v45.2"">
      <wd:Candidate_Reference>
        <wd:ID wd:type=""Candidate_ID"">{candidateId}</wd:ID>
      </wd:Candidate_Reference>

      <wd:Candidate_Attachment_Data>
        <wd:Attachment_Data>
          <wd:ID>{attachmentId}</wd:ID>
          <wd:Filename>{filename}</wd:Filename>
          <wd:File_Content>{base64File}</wd:File_Content>
          <wd:Mime_Type_Reference>
            <wd:ID wd:type=""Content_Type_ID"">{contentType}</wd:ID>
          </wd:Mime_Type_Reference>
          <wd:Comment>{comment}</wd:Comment>
        </wd:Attachment_Data>

        <wd:Document_Category_Reference>
          <wd:ID wd:type=""Document_Category__Workday_Owned__ID"">{documentCategory}</wd:ID>
        </wd:Document_Category_Reference>
      </wd:Candidate_Attachment_Data>
    </wd:Put_Candidate_Attachment_Request>
  </env:Body>
</env:Envelope>";


            // Optional: ensure TLS 1.2+ (Workday requires modern TLS)
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12
                                                 | SecurityProtocolType.Tls11; // TLS 1.3 if supported
                                                                               // Encode credentials
            string Token = GetTokenDetails(clientRowId);

            var request = (HttpWebRequest)WebRequest.Create(url);
            // Add Authorization header
            request.Headers["Authorization"] = "Bearer " + Token;
            request.Method = "POST";
            request.ContentType = "text/xml; charset=utf-8";   // SOAP uses text/xml
            request.Headers.Add("SOAPAction", "");             // Workday usually ignores SOAPAction; empty is fine
            request.Timeout = 100_000;                         // 100 seconds; adjust as needed
            request.KeepAlive = true;

            // Write SOAP XML into the request stream
            byte[] payloadBytes = Encoding.UTF8.GetBytes(soapXml);
            request.ContentLength = payloadBytes.Length;
            using (var reqStream = request.GetRequestStream())
            {
                reqStream.Write(payloadBytes, 0, payloadBytes.Length);
            }

            // Read response (success or SOAP Fault)
            try
            {
                using (var response = (HttpWebResponse)request.GetResponse())
                using (var reader = new StreamReader(response.GetResponseStream()))
                {
                    string responseXml = reader.ReadToEnd();
                    //string responseXml = reader.ReadToEnd();
                    if (response.StatusCode.ToString() == "OK")
                    {
                        InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Success", "BgvReport", "RequestData:" + RequestData, responseXml, "API", 0);
                    }
                    else
                    {
                        InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", "BgvReport", "RequestData:" + RequestData, responseXml, "API", 0);
                    }
                }
            }
            catch (WebException ex)
            {
                // Capture response body even on errors (useful for Workday SOAP faults)
                if (ex.Response is HttpWebResponse errorResponse)
                {
                    var respStream = errorResponse.GetResponseStream();
                    var reader = new StreamReader(respStream);
                    string errorBody = reader.ReadToEnd();
                }
                else
                {
                }
                InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", "BgvReport", "RequestData:" + RequestData, ex.Message.ToString(), "API", 0);

            }
            return errorDetails;

        }
        public string GetTokenDetails(int clientRowId)
        {
            string res = "";
            string url = "https://wd3-services1.myworkday.com/ccx/oauth2/diconium/token";
            var ClientAuth = Dc.SP_GetClientAPIDetails(Convert.ToInt32(clientRowId), "Basic", "Bearer Token");
            string clientId = "";       // Postman Authorization -> Basic Auth -> Username
            string clientSecret = ""; // Postman Authorization -> Basic Auth -> Password
            string refreshToken = ""; // Postman Body -> x-www-form-urlencoded -> refresh_token
            if (ClientAuth.Rows.Count > 0)
            {
                clientId = Convert.ToString(ClientAuth.Rows[0]["UserName"]).Trim();
                clientSecret = Convert.ToString(ClientAuth.Rows[0]["Password"]).Trim();
                refreshToken = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]).Trim();
            }

            try
            {
                string formBody = $"grant_type=refresh_token&refresh_token={Uri.EscapeDataString(refreshToken)}";
                byte[] bodyBytes = Encoding.UTF8.GetBytes(formBody);

                var request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "POST";
                request.ContentType = "application/x-www-form-urlencoded"; // matches Postman selection
                request.Accept = "application/json";                       // Workday returns JSON
                request.Headers["Authorization"] = "Basic " +
                    Convert.ToBase64String(Encoding.ASCII.GetBytes($"{clientId}:{clientSecret}"));

                // Write body
                request.ContentLength = bodyBytes.Length;
                using (var reqStream = request.GetRequestStream())
                {
                    reqStream.Write(bodyBytes, 0, bodyBytes.Length);
                }

                // Read response
                using (var response = (HttpWebResponse)request.GetResponse())
                using (var stream = response.GetResponseStream())
                using (var reader = new StreamReader(stream))
                {
                    string result = reader.ReadToEnd();

                    JObject obj = JObject.Parse(result);
                    res = obj["access_token"].ToString();
                }
            }
            catch (WebException wex)
            {
                string errorBody = "";
                if (wex.Response != null)
                {
                    using (var stream = wex.Response.GetResponseStream())
                    using (var reader = new StreamReader(stream))
                        errorBody = reader.ReadToEnd();
                    res = errorBody;

                }
            }
            catch (Exception ex)
            {
                res = Convert.ToString(ex.Message);
            }
            return res;
        }

