        private string CompressToZip(Byte[] attachmentModel, string pdfFileName, string zipFileName)
        {
            FileContentResult fileContentResult = null;
            using (var compressedStream = new MemoryStream())
            {
                using (ZipArchive archive = new ZipArchive(compressedStream, ZipArchiveMode.Update, false))
                {
                    var zipArchiveEntry = archive.CreateEntry(pdfFileName);
                    using (var originalFileStream = new MemoryStream(attachmentModel))
                    {
                        using (var zipEntryStream = zipArchiveEntry.Open())
                        {
                            originalFileStream.CopyTo(zipEntryStream);
                        }
                    }
                }
                fileContentResult = new FileContentResult(compressedStream.ToArray(), "application/zip")
                {
                    FileDownloadName = zipFileName
                };
            }
            String files = Convert.ToBase64String(fileContentResult.FileContents);
            return files;
        }
