        public static void WriteLog(string StrJsonResponse, string StrUnique_id, string StrCandidateId, string CompanyName, string FileName, string StrDataType)
        {
            try
            {
                StreamWriter log;
                FileStream fileStream = null;
                DirectoryInfo logDirInfo = null;
                FileInfo logFileInfo;



                //string logFilePath = "D:\\LogsDetails\\" + CompanyName + "\\" + FileName + "\\";  ////Using Test Server



                ////===============Using for Live server=========================
                string logFilePath = "D:\\wwwroot2\\LogsDetails\\" + CompanyName + "\\" + FileName + "\\";  ////Using Live server
                if (StrDataType == "Data-list")
                {
                    logFilePath = logFilePath + StrDataType + System.DateTime.Now.ToString("-dd-MM-yyyy-hh-mm-ss") + "." + "txt";



                }
                else
                {
                    logFilePath = logFilePath + StrDataType + "." + "txt";
                }
                logFileInfo = new FileInfo(logFilePath);
                logDirInfo = new DirectoryInfo(logFileInfo.DirectoryName);
                if (!logDirInfo.Exists) logDirInfo.Create();
                if (!logFileInfo.Exists)
                {
                    fileStream = logFileInfo.Create();
                }
                else
                {
                    fileStream = new FileStream(logFilePath, FileMode.Append);
                }
                log = new StreamWriter(fileStream);
                log.WriteLine(StrJsonResponse);
                log.Close();
            }
            catch (Exception ex)
            {
                ex.Message.ToString();
            }
        }
