        public static string PostClientReviewLTIMindtreeStatusAndReport(int personalRowId, string ClientRefId, string reportStatus, string reportColor, string ReportUploadedName, string ReportComment, int clientRowId, DataTable dtPQP, int subCheckRowID, string APIRemarks)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
            string apiResponse = "";
            string StrData = "";
            try
            {

                if (dtPQP.Rows.Count > 0)
                {
                    ClientCustomize cc = new ClientCustomize();
                    DataTable tblChkDetail = cc.GetAPICurrentCheckStatusLTMT(personalRowId, subCheckRowID);
                    DataTable dt = new DataTable();
                    string strRequestID = "";
                    string strCandidateID = "";
                    if (personalRowId > 416777)
                    {
                        strRequestID = Convert.ToString(dtPQP.Rows[0]["ClientRefID"]);
                        strCandidateID = Convert.ToString(dtPQP.Rows[0]["EmployeeID"]);
                        ClientRefId = strRequestID;
                    }
                    else
                    {
                        strRequestID = Convert.ToString(dtPQP.Rows[0]["EmployeeID"]);
                        strCandidateID = Convert.ToString(dtPQP.Rows[0]["ClientRefID"]);
                        ClientRefId = strCandidateID;
                    }
                    string CheckDetails = "";
                    DataBaseConnections Dc = new DataBaseConnections();
                    string UName = "";
                    string psw = "";
                    var ClientAuth = Dc.SP_GetClientAPIDetails(Convert.ToInt32(clientRowId), "Bearer Token", "BGVCheckStatus");
                    if (ClientAuth.Rows.Count > 0)
                    {
                        UName = Convert.ToString(ClientAuth.Rows[0]["UserName"]);
                        psw = Convert.ToString(ClientAuth.Rows[0]["Password"]);
                    }
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("----------------------------API SP_GetClientAPIDetails working fine-----------------" + "UName:" + UName);
                    StrBuilderObj.Append(Environment.NewLine);
                    //string URL = "https://LTIiVerifyTestAPI.azurewebsites.net/VendorUpdateService/UpdateBGVCheckStatusRowwise";
                    ////=======Production===========
                    string URL = "https://ltiiverifyapiprodnew.azurewebsites.net/VendorUpdateService/UpdateBGVCheckStatusRowwise";
                    UpdateCandidateChecksStatus objAcks = new UpdateCandidateChecksStatus();
                    List<LiChecksDetail> liChecksDetails = new List<LiChecksDetail>();
                    LiChecksDetail chkObj = new LiChecksDetail();
                    List<LiChecksDetail> liChecks = new List<LiChecksDetail>();
                    LiChecksDetail objCheck = new LiChecksDetail();
                    string bgvStatus = "";
                    if (tblChkDetail.Rows.Count > 0)
                    {
                        for (int i = 0; i < tblChkDetail.Rows.Count; i++)
                        {
                            objCheck = new LiChecksDetail();
                            objCheck.CheckCode = Convert.ToString(tblChkDetail.Rows[i]["ClientCheckCode"]);
                            objCheck.CheckName = Convert.ToString(tblChkDetail.Rows[i]["ClientCheckName"]);
                            objCheck.CheckStatus = Convert.ToString(tblChkDetail.Rows[i]["CheckStatusNO"]);
                            objCheck.CheckRemarks = APIRemarks;
                            objCheck.CompletedDate = Convert.ToString(tblChkDetail.Rows[i]["CheckCompletionDate"]);
                            objCheck.ModeOfVerficationRequired = Convert.ToString(tblChkDetail.Rows[i]["ModeOfVerification"]);
                            objCheck.ModeOfVerficationPerformed = Convert.ToString(tblChkDetail.Rows[i]["ModeOfVerification"]);
                            bgvStatus = Convert.ToString(tblChkDetail.Rows[i]["CheckStatus"]);
                            if (objCheck.CheckRemarks != null && objCheck.CheckStatus != null && objCheck.ModeOfVerficationRequired != null && objCheck.CompletedDate != null)
                            {
                                liChecks.Add(objCheck);
                                CheckDetails += ",CheckName:" + objCheck.CheckName + ",CheckStatus:" + bgvStatus + "," + "Remark:" + objCheck.CheckRemarks;
                            }
                        }
                    }
                    StrData = "PersonalRowId:" + personalRowId + " ,SubCheckRowID:" + subCheckRowID + " ,ClientCheckName:" + tblChkDetail.Rows[0]["ClientCheckName"];
                    if (tblChkDetail.Rows.Count > 0)
                    {
                        for (int i = 0; i < tblChkDetail.Rows.Count; i++)
                        {
                            if (Convert.ToString(tblChkDetail.Rows[i]["CheckStatus"]).Trim() == "Client Review")
                            {
                                bgvStatus = "Client Review";
                                break;
                            }
                        }
                    }
                    List<LiReportDetail> liReportDetails = new List<LiReportDetail>();
                    LiReportDetail liRptObj = new LiReportDetail();

                    Token token = GetAccessToken(UName, psw);
                    StrBuilderObj.Append(Environment.NewLine);
                    StrBuilderObj.Append("----------------------------API GetAccessToken working fine-----------------" + "token:" + token);
                    StrBuilderObj.Append(Environment.NewLine);

                    objAcks.CandidateID = strCandidateID.Trim();
                    objAcks.PSNO = Convert.ToString(dtPQP.Rows[0]["CandidateCode"]).Trim();
                    objAcks.Name = Convert.ToString(dtPQP.Rows[0]["CandidateFullName"]);
                    //objAcks.VendorName = "F7E68849";
                    ////=====Production=====================
                    objAcks.VendorName = "9FEE5CFF";
                    objAcks.RequestID = strRequestID.Trim();
                    objAcks.liChecksDetails = liChecks;
                    DataTable dts = new DataTable();
                    dts = cc.GetLtiMindtreeReportType(personalRowId);
                    //--------For ReportDetail-------------------
                    if (ReportUploadedName.Trim() != "")
                    {
                        liRptObj.ReportFileName = ReportUploadedName.Trim();
                        liRptObj.ReportFileExtention = ReportUploadedName.Trim().Split('.')[1];
                        liRptObj.ReportAttachment = Convertbase64FromFilesClientReview(ReportUploadedName);
                        liRptObj.VendorReferenceID = Convert.ToString(dtPQP.Rows[0]["CompanyRefNo"]);
                        if (bgvStatus == "Client Review")
                        {
                            liRptObj.ReportType = "7";
                            liRptObj.ReportStatus = "7";
                        }

                        liReportDetails.Add(liRptObj);
                        objAcks.liReportDetails = liReportDetails;
                    }
                    else
                    {
                        liRptObj.ReportFileName = "";
                        liRptObj.ReportFileExtention = "";
                        liRptObj.ReportAttachment = "";
                        liRptObj.VendorReferenceID = "";
                        liRptObj.ReportType = "";
                        liRptObj.ReportStatus = "";
                        liReportDetails.Add(liRptObj);
                        objAcks.liReportDetails = liReportDetails;
                    }
                    HttpClientHandler handler = new HttpClientHandler();
                    HttpClient client = new HttpClient(handler);
                    client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token.access_token);
                    string json = "[ " + JsonConvert.SerializeObject(objAcks) + " ]";
                    StrBuilderObj.Append(json.ToString());
                    var data = new StringContent(json, Encoding.UTF8, "application/json");
                    var APIResponse = client.PostAsync(URL, data).Result;
                    apiResponse = APIResponse.StatusCode.ToString();
                    if (apiResponse == "OK")
                    {
                        InsertAPI_AuditDetail_LTI2(ClientRefId, clientRowId, "Success", "LTIMindtreeClientReviewTag", StrData + CheckDetails, apiResponse, "API", subCheckRowID);

                    }
                    else
                    {
                        InsertAPI_AuditDetail_LTI2(ClientRefId, clientRowId, "Failed", "LTIMindtreeClientReviewTag", StrData + CheckDetails, apiResponse, "API", subCheckRowID);
                        WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "LTIMindtreeClientReviewTag", clientRowId + "-" + personalRowId + "-Failed");

                    }
                }
            }
            catch (Exception ex)
            {
                StrBuilderObj.Append("Failed" + ex.ToString());
                InsertAPI_AuditDetail_LTI2(ClientRefId, clientRowId, "Failed", "LTIMindtreeClientReviewTagException", StrData + "CheckDetails", "Exception:-" + ex.ToString() + " apiResponse:-" + apiResponse, "API", subCheckRowID);
                WriteLog(StrBuilderObj.ToString(), "", "", "LTIMindTree", "LTIMindtreeClientReviewTagException", clientRowId + "-" + personalRowId + "-Failed");

            }
            return apiResponse;
        }

