        public static void InsertAPI_AuditDetail_LTI2(string UniqueReferenceID, int ClientRowID, string Status, string DataType, string DataValue, string Remarks, string CreatedBy, int SubCheckRowID)
        {
            DAS.ExecuteDataTable(DAS.ConnectionString, CommandType.StoredProcedure, "InsertAPI_AuditDetail_LTI",
                   DAS.CreateParameter("@UniqueReferenceID", SqlDbType.VarChar, UniqueReferenceID, ParameterDirection.Input, 200, false),
                   DAS.CreateParameter("@ClientRowID", SqlDbType.Int, ClientRowID, ParameterDirection.Input, 8, false),
                   DAS.CreateParameter("@Status", SqlDbType.VarChar, Status, ParameterDirection.Input, 50, false),
                   DAS.CreateParameter("@DataType", SqlDbType.VarChar, DataType, ParameterDirection.Input, 400, false),
                   DAS.CreateParameter("@DataValue", SqlDbType.VarChar, DataValue, ParameterDirection.Input, -1, false),
                   DAS.CreateParameter("@Remarks", SqlDbType.VarChar, Remarks, ParameterDirection.Input, -1, false),
                   DAS.CreateParameter("@CreatedBy", SqlDbType.VarChar, CreatedBy, ParameterDirection.Input, 100, false),
                   DAS.CreateParameter("@SubCheckRowID", SqlDbType.Int, SubCheckRowID, ParameterDirection.Input, 8, false)
                                  );
        }
