        public void InfovisionBgvStatusandReport(int clientRowId, int PersonalRowid, int SubcheckrowId, string CompanyRefNo, string uniqueID, string CheckName, string CheckID, string CheckStatus, int APIAutoID)
        {
            StringBuilder StrBuilderObj = new StringBuilder();
            try
            {
                StrBuilderObj.Clear();
                string json = "";
                string Api_Key = "";
                string Authorization = "";
                string apiResponse = "";
                var ClientAuth = Dc.SP_GetClientAPIDetails(Convert.ToInt32(clientRowId), "Authorization", "BGVReports");
                if (ClientAuth.Rows.Count > 0)
                {
                    Authorization = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]).Trim();
                    Api_Key = Convert.ToString(ClientAuth.Rows[0]["Password"]).Trim();
                }
                var url = "https://productivv.ivlglobal.com/api/Candidate/UpdateBGVStatus";
                string strPersonalRowId = Convert.ToString(PersonalRowid);
                string ImgName = CompanyRefNo + ".pdf";
                HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(url);
                httpWebRequest.Method = "POST";
                httpWebRequest.ContentType = "application/json";
                httpWebRequest.Headers.Add("Api-Key", Api_Key);
                httpWebRequest.Headers.Add("Authorization", "Basic " + Authorization);


                using (var streamWriter = new
                StreamWriter(httpWebRequest.GetRequestStream()))
                {
                    json = "{\"verificationReferenceId\":\"" + CompanyRefNo + "\",\"UniqueReferenceID\":\"" + uniqueID + "\",\"CheckName\":\"" + CheckName + "\",\"CheckID\":\"" + CheckID + "\",\"CheckStatus\":\"" + CheckStatus + "\"}";
                    streamWriter.Write(json);
                }
                var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse();
                apiResponse = httpResponse.StatusCode.ToString();
                if (apiResponse == "OK")
                {
                    InsertAPI_AuditDetail_LTI(uniqueID, clientRowId, "Success", CheckStatus, "RequestData:" + "PersonalRowid: " + PersonalRowid, "OK", "API", SubcheckrowId);

                }
                else
                {
                    InsertAPI_AuditDetail_LTI(uniqueID, clientRowId, "Failed", CheckStatus, "RequestData:" + "PersonalRowid: " + PersonalRowid, apiResponse, "API", SubcheckrowId);
                }
            }
            catch (Exception ex)
            {
                string msg = ex.Message;
                InsertAPI_AuditDetail_LTI(uniqueID, clientRowId, "Failed", CheckStatus, "RequestData:" + "PersonalRowid: " + PersonalRowid, msg, "API", SubcheckrowId);
            }

        }
