        public static string DownloadCandidateDocPWC(string DocumentName, string DocumentType)
        {
            string res = "";
            StringBuilder StrBuilderObj = new StringBuilder();
            StrBuilderObj.Clear();
            try
            {
                string Documentpath;

                if (DocumentType.ToLower().Trim() == "document")
                {
                    Documentpath = @"D:\\wwwroot2\\Documents\\CandidateDocuments\\ProvidedDocuments\\";
                }
                else
                {
                    Documentpath = @"D:\wwwroot2\Documents\CandidateDocuments\CandidateReport\";
                }
                string url = ConfigurationManager.AppSettings["DocumentBaseURL"].ToString() + "Get-Doc-File-Document/";
                string jsonData = "{\"Documentpath\":\"" + Documentpath + "\",\"DocumentName\":\"" + DocumentName + "\"}";
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "POST";
                request.ContentType = "application/json"; // Change to "application/x-www-form-urlencoded" if needed
                request.Accept = "application/json";
                using (var streamWriter = new StreamWriter(request.GetRequestStream()))
                {
                    streamWriter.Write(jsonData);
                    streamWriter.Flush();
                }
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                {
                    res = reader.ReadToEnd();
                    JObject json = JObject.Parse(res);
                    string documentValue = json["DocumentValue"]?.ToString();
                    res = documentValue;


                }

            }
            catch (Exception ex)
            {
                res = "";
            }
            return res;
        }

