        public string GetToken(int clientRowId, string Error)
        {
            string rspo = "";
            try
            {
                AddPQPersonalViewModel model = new AddPQPersonalViewModel();
                var GetToken = Dc.sp_GetTokenDetails(clientRowId);
                if (GetToken.Rows.Count > 0 && Error == "")
                {
                    rspo = Convert.ToString(GetToken.Rows[0]["Token"]);
                }
                else
                {
                    /////var url = "https://usosqa.wipro.com/oauth2/token";  //// Testing
                    var url = "https://usos.wipro.com/oauth2/token"; ////Live
                    var ClientAuth = Dc.SP_GetClientAPIDetails(clientRowId, "Authorization Bearer", "TokenLive");
                    string Token_Basic = "";
                    if (ClientAuth.Rows.Count > 0)
                    {
                        Token_Basic = Convert.ToString(ClientAuth.Rows[0]["Password"]);
                    }
                    var request = (HttpWebRequest)WebRequest.Create(url);
                    request.Method = "POST";
                    request.ContentType = "application/x-www-form-urlencoded";
                    request.Headers["Authorization"] = Token_Basic;
                    // Prepare body data
                    string postData = "grant_type=client_credentials";
                    byte[] dataBytes = Encoding.UTF8.GetBytes(postData);

                    // Write body
                    using (Stream requestStream = request.GetRequestStream())
                    {
                        requestStream.Write(dataBytes, 0, dataBytes.Length);
                    }
                    // Get response
                    using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                    using (StreamReader reader = new StreamReader(response.GetResponseStream()))
                    {
                        string result = reader.ReadToEnd();
                        JObject obj = JObject.Parse(result);
                        rspo = obj["access_token"].ToString();
                        var res = Dc.sp_SaveTokenDetails(clientRowId, rspo);
                    }
                }

            }
            catch (Exception ex)
            {
                string message = ex.Message;
                InsertAPI_AuditDetail_LTI("Token_Wipro", clientRowId, "Token_Wipro2", message, "Failed", "100", "", 0);
            }
            return rspo;
        }
        public string API_CandidateDetails_Status(string unique_id, string action, string bgvStatus, string RemarkStatus, int clientRowId, int PersonalRowId, int subcheckRowID = 0)
        {
            string res = "";
            string compactJson = "";
            string base64CipherText = "";
            string CipherTextbase64 = "";
            string bgvSubStatus = "";
            try
            {
                AddPQPersonalViewModel model = new AddPQPersonalViewModel();
                ////var Candidate_Details_Url = "https://usosqa.wipro.com/iverify/1.0.0/verification-status/update"; /// Testing 
                var Candidate_Details_Url = "https://usos.wipro.com/iverify/1.0.0/verification-status/update"; /// Live
                RootobjectSave rootobjectSave = new RootobjectSave();
                compactJson = BuildJsonFromDataTable(unique_id, "checkdetails", action, bgvStatus, RemarkStatus, PersonalRowId, subcheckRowID);
                var settings = new JsonSerializerSettings
                {
                    // prevents auto-conversion of date-like strings
                    //DateParseHandling = DateParseHandling.None,
                    // safer defaults
                    //MissingMemberHandling = MissingMemberHandling.Ignore,
                    //NullValueHandling = NullValueHandling.Include
                };
                var obj = JsonConvert.DeserializeObject<RootobjectSave>(compactJson, settings);
                bgvSubStatus = Convert.ToString(obj.inputs.bgvSubStatus);
                if (subcheckRowID != 0)
                {
                    bgvSubStatus = Convert.ToString(obj.inputs.entityStatusData[0].entityStatus);
                }
                else if (RemarkStatus == "Completed")
                {
                    bgvSubStatus = RemarkStatus;
                }
                else if (bgvSubStatus == "")
                {
                    bgvSubStatus = "WIP";
                }
                var ClientAuth = Dc.SP_GetClientAPIDetails(clientRowId, "Authorization Bearer", "TokenLive");
                string Enter_Secret_Key_AccessToken = "";
                string Enter_IV = "";
                if (ClientAuth.Rows.Count > 0)
                {
                    Enter_Secret_Key_AccessToken = Convert.ToString(ClientAuth.Rows[0]["AuthorizationKey"]);
                    Enter_IV = Convert.ToString(ClientAuth.Rows[0]["UserName"]);
                }
                base64CipherText = AesCbcPkcs7.EncryptToBase64(compactJson, Enter_Secret_Key_AccessToken, Enter_IV);
                var request = (HttpWebRequest)WebRequest.Create(Candidate_Details_Url);
                request.Method = "POST";
                request.ContentType = "text/plain; charset=utf-8";
                string TokenDat = GetToken(317, "");
                request.Headers["Authorization"] = "Bearer " + TokenDat;
                request.Headers["AccessToken"] = Enter_Secret_Key_AccessToken;
                string jsonresult = "";
                // Write the Base64 string as-is (no quotes, no JSON)
                byte[] bodyBytes = Encoding.UTF8.GetBytes(base64CipherText);
                request.ContentLength = bodyBytes.Length;

                using (var requestStream = request.GetRequestStream())
                {
                    requestStream.Write(bodyBytes, 0, bodyBytes.Length);
                }
                try
                {
                    // Get response
                    WebHeaderCollection headers = new WebHeaderCollection();
                    using (var response = (HttpWebResponse)request.GetResponse())
                    using (var reader = new StreamReader(response.GetResponseStream()))
                    {
                        jsonresult = reader.ReadToEnd();
                        CipherTextbase64 = AesCbcPkcs7.DecryptFromBase64(jsonresult, Enter_Secret_Key_AccessToken, Enter_IV);
                        if (CipherTextbase64.Contains("success"))
                        {
                            res = CipherTextbase64;
                            InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Success", bgvSubStatus, "RequestData:" + compactJson, CipherTextbase64, "API", subcheckRowID);
                        }
                        else
                        {
                            InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", bgvSubStatus, "RequestData:" + compactJson, CipherTextbase64, "API", subcheckRowID);
                        }
                        headers = response.Headers;
                    }
                    foreach (string key in headers.AllKeys)
                    {
                        if (key.ToString() == "activityid")
                        {
                            string Varlues = headers[key];
                            insertCaseRegistrationLog(Convert.ToString(clientRowId), unique_id, "SendCandidateStatusAPI", key.ToString(), Varlues);
                        }
                        if (key.ToString() == "correlationid")
                        {
                            string Varlues = headers[key];
                            insertCaseRegistrationLog(Convert.ToString(clientRowId), unique_id, "SendCandidateStatusAPI", key.ToString(), Varlues);
                            break;
                        }
                    }
                    string jsonHeaders = JsonConvert.SerializeObject(headers.ToString(), Newtonsoft.Json.Formatting.Indented);
                    insertCaseRegistrationLog(Convert.ToString(clientRowId), unique_id, "SendCandidateStatusAPI", "GetHeadersDetails", jsonHeaders);

                }
                catch (WebException wex)
                {
                    string errorBody = "";
                    if (wex.Response != null)
                    {
                        using (var stream = wex.Response.GetResponseStream())
                        using (var reader = new StreamReader(stream))
                            errorBody = reader.ReadToEnd();
                        res = errorBody;
                        string message = res;
                        if (message.Contains("Invalid JWT token. Make sure you have provided the correct security credentials"))
                        {
                            TokenDat = GetToken(317, message);
                        }
                    }
                    InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", bgvSubStatus, "RequestData:" + compactJson, CipherTextbase64, "API", subcheckRowID);
                }
            }
            catch (Exception ex)
            {
                string message = Convert.ToString(ex.Message);
                InsertAPI_AuditDetail_LTI(unique_id, clientRowId, "Failed", bgvSubStatus, "RequestData:" + compactJson, "Exception: " + message + "Res: " + CipherTextbase64, "API", subcheckRowID);
            }
            return res;
        }

        public static string BuildJsonFromDataTable(string UniqueID, string RequestType, string action, string bgvSubStatus, string remarks, int personalRowID, int subcheckRowID)
        {
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = cc.GetWiproClientMapDetails(personalRowID, subcheckRowID, bgvSubStatus, RequestType);

            if (dt == null || dt.Rows.Count == 0)
                throw new Exception("No data returned from GetWiproClientMapDetails.");

            // Map DataTable rows to entityStatusData list
            List<Entitystatusdata> list = new List<Entitystatusdata>();
            string Status_DESC = "";
            string Status_CODE = "";
            foreach (DataRow row in dt.Rows)
            {
                if (Convert.ToString(row["CheckEntityId"]) != "" && Convert.ToString(row["entityDataId"]) != "")
                {
                    if (Convert.ToString(row["Status_CODE"]) == "CLEARRPT")
                    {
                        Status_DESC = Convert.ToString(row["ColorCode"]);
                    }
                    else
                    {
                        Status_DESC = row.Table.Columns.Contains("Status_DESC")
                                    ? row["Status_DESC"]?.ToString()
                                    : null;
                    }
                    if (Convert.ToString(row["Status_CODE"]) == "" && Convert.ToString(row["Status_CODE"]) != "CLEARRPT")
                    {
                        bgvSubStatus = "";
                        action = "save";
                        Status_CODE = "AGINPROG";
                    }
                    else
                    {
                        Status_CODE = Convert.ToString(row["Status_CODE"]);
                    }
                    if (Convert.ToString(row["Status_DESC"]) != "" && Convert.ToString(row["Status_CODE"]) != "CLEARRPT")
                    {
                        string text = Regex.Replace(Convert.ToString(row["Remarks"]), "<.*?>", string.Empty);
                        Status_DESC = Convert.ToString(text);
                    }
                    if (Convert.ToString(row["Status_CODE"]) == "MAJDISC")
                    {
                        string text = Regex.Replace(Convert.ToString(row["Remarks"]), "<.*?>", string.Empty);
                        Status_DESC = Convert.ToString(text);
                    }
                    list.Add(new Entitystatusdata
                    {
                        entityId = row["CheckEntityId"]?.ToString(),
                        entityDataId = row["entityDataId"]?.ToString(),
                        entityStatus = Status_CODE,
                        remarks = Status_DESC
                    });
                }
            }
            if (remarks == "")
            {
                remarks = Status_DESC;
            }
            // Fill header object
            Inputs header = new Inputs
            {
                entityStatusData = list.ToArray(),
                companyCode = dt.Rows[0]["companyCode"]?.ToString(),
                masterId = dt.Rows[0]["BGVMASTERID"]?.ToString(),
                module = dt.Rows[0]["Module"]?.ToString(),
                userId = dt.Rows[0]["AGENCYID"]?.ToString(),
                action = action,
                bgvType = dt.Rows[0]["BGVTYPE"]?.ToString(),
                remarks = remarks,
                bgvSubStatus = bgvSubStatus
            };

            // Set userLevel conditionally
            if (!string.Equals(bgvSubStatus, "insufficiency", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(header.bgvType, "bgv2", StringComparison.OrdinalIgnoreCase))
            {
                header.userLevel = "AG";
            }

            // Create root wrapper
            RootobjectSave root = new RootobjectSave
            {
                inputs = header
            };
            // Serialize using Newtonsoft
            var settings = new JsonSerializerSettings
            {
                //ContractResolver = new CamelCasePropertyNamesContractResolver(),
                //NullValueHandling = NullValueHandling.Ignore,
                //Formatting = Newtonsoft.Json.Formatting.Indented
            };

            return JsonConvert.SerializeObject(root, settings);
        }
