        public static string BuildJsonFromDataTable_L1Insuff(string UniqueID, string RequestType, string action, string bgvSubStatus, string remarks, int personalRowID, string subcheckRowID)
        {
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = cc.GetWiproClientMapDetails_L1Insuff(personalRowID, subcheckRowID, bgvSubStatus, RequestType);

            if (dt == null || dt.Rows.Count == 0)
                throw new Exception("No data returned from GetWiproClientMapDetails.");

            // Map DataTable rows to entityStatusData list
            List<Entitystatusdata> list = new List<Entitystatusdata>();
            string Status_DESC = "";
            string Status_CODE = "";
            foreach (DataRow row in dt.Rows)
            {
                if (Convert.ToString(row["CheckEntityId"]) != "" && Convert.ToString(row["entityDataId"]) != "")
                {
                    if (Convert.ToString(row["Status_CODE"]) == "CLEARRPT")
                    {
                        Status_DESC = Convert.ToString(row["ColorCode"]);
                    }
                    else
                    {
                        Status_DESC = row.Table.Columns.Contains("Status_DESC")
                                    ? row["Status_DESC"]?.ToString()
                                    : null;
                    }
                    if (Convert.ToString(row["Status_CODE"]) == "" && Convert.ToString(row["Status_CODE"]) != "CLEARRPT")
                    {
                        bgvSubStatus = "";
                        action = "save";
                        Status_CODE = "AGINPROG";
                    }
                    else
                    {
                        Status_CODE = Convert.ToString(row["Status_CODE"]);
                    }
                    if (Convert.ToString(row["Status_DESC"]) != "" && Convert.ToString(row["Status_CODE"]) != "CLEARRPT")
                    {
                        string text = Regex.Replace(Convert.ToString(row["Remarks"]), "<.*?>", string.Empty);
                        Status_DESC = Convert.ToString(text);
                    }
                    list.Add(new Entitystatusdata
                    {
                        entityId = row["CheckEntityId"]?.ToString(),
                        entityDataId = row["entityDataId"]?.ToString(),
                        entityStatus = Status_CODE,
                        remarks = Status_DESC
                    });
                }
            }
            if (remarks == "")
            {
                remarks = Status_DESC;
            }
            // Fill header object
            Inputs header = new Inputs
            {
                entityStatusData = list.ToArray(),
                companyCode = dt.Rows[0]["companyCode"]?.ToString(),
                masterId = dt.Rows[0]["BGVMASTERID"]?.ToString(),
                module = dt.Rows[0]["Module"]?.ToString(),
                userId = dt.Rows[0]["AGENCYID"]?.ToString(),
                action = action,
                bgvType = dt.Rows[0]["BGVTYPE"]?.ToString(),
                remarks = remarks,
                bgvSubStatus = bgvSubStatus
            };

            // Set userLevel conditionally
            if (!string.Equals(bgvSubStatus, "insufficiency", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(header.bgvType, "bgv2", StringComparison.OrdinalIgnoreCase))
            {
                header.userLevel = "AG";
            }

            // Create root wrapper
            RootobjectSave root = new RootobjectSave
            {
                inputs = header
            };
            // Serialize using Newtonsoft
            var settings = new JsonSerializerSettings
            {
                //ContractResolver = new CamelCasePropertyNamesContractResolver(),
                //NullValueHandling = NullValueHandling.Ignore,
                //Formatting = Newtonsoft.Json.Formatting.Indented
            };

            return JsonConvert.SerializeObject(root, settings);
        }

